/**
 * Original design by Gustavo Fior (@gustavo-fior), co-founder Abdul Haidar, and Foglamp Labs.
 * Extracted AS-IS from foglamp-labs/foglamp: apps/web/src/components/app/onboarding-panel.tsx.
 * Licensed under Apache-2.0.
 */
"use client";

import { Button } from "../../ui/button";
import {
  Card,
  CardAction,
  CardDescription,
  CardHeader,
  CardTitle,
} from "../../ui/card";
import {
  IconBookFilled,
  IconClipboardCheckFilled,
  IconExternalLink,
} from "@tabler/icons-react";
import { BorderBeam } from "border-beam";

import { CopyIcon } from "../../widgets/leaf/copy-icon";
import { useCopied } from "../../hooks/use-copied";
import { DOCS_URL, buildKeyedPrompt } from "../marketing/cta/agent-prompt";

export type OnboardingPanelBlockProps = {
  /** Plaintext key supplied by the host after its own secure key flow. */
  apiKey?: string | null;
  /** Optional prebuilt prompt, for hosts that own prompt generation. */
  prompt?: string;
  docsUrl?: string;
  onPromptCopied?: () => void;
};

export function OnboardingPanelBlock({
  apiKey,
  prompt: promptOverride,
  docsUrl = DOCS_URL,
  onPromptCopied,
}: OnboardingPanelBlockProps = {}) {
  const { copied, markCopied } = useCopied(2000);
  const prompt = promptOverride ?? (apiKey ? buildKeyedPrompt(apiKey) : null);
  const copy = () => {
    if (!prompt) return;
    void navigator.clipboard.writeText(prompt);
    markCopied();
    onPromptCopied?.();
  };

  return (
    <div className="grid gap-4 sm:grid-cols-2 px-8">
      <BorderBeam
        size="pulse-inner"
        colorVariant="colorful"
        strength={0.6}
        borderRadius={16}
      >
        {/* The beam shapes its ring with clip-path: inset(round) — always a
            circular arc, immune to corner-shape — so it can't be a squircle.
            corner-round! drops the Card's default superellipse to a plain round
            corner at the same 22px (rounded-3xl) radius so the edges align. */}
        <Card className="h-full corner-round! rounded-2xl!">
          <CardHeader>
            <CardTitle className="flex items-center gap-1.5">
              <IconClipboardCheckFilled className="size-4" />
              Prompt
            </CardTitle>
            <CardDescription>
              Paste this into your coding agent to install and wire up the SDK.
            </CardDescription>
            <CardAction className="self-center">
              {prompt ? (
                <Button
                  size="sm"
                  variant="default"
                  onClick={copy}
                  aria-label="Copy prompt"
                >
                  <CopyIcon
                    copied={copied}
                    // Inverted greens: the default Button's chip flips its bg
                    // against the theme.
                    checkClassName="text-green-400 dark:text-green-600"
                  />
                  Copy the prompt
                </Button>
              ) : (
                <p className="text-sm text-muted-foreground">
                  Preparing your key…
                </p>
              )}
            </CardAction>
          </CardHeader>
        </Card>
      </BorderBeam>

      {/* No beam here, but match the beamed card's plain round corner so the
          side-by-side pair stays visually consistent. */}
      <Card className="h-full corner-round!">
        <CardHeader>
          <CardTitle className="flex items-center gap-1.5">
            <IconBookFilled className="size-4" />
            Old School
          </CardTitle>
          <CardDescription>
            Prefer to wire it up by hand? Follow the full instrumentation guide.
          </CardDescription>
          <CardAction className="self-center">
            <Button
              size="sm"
              variant="secondary"
              render={<a href={docsUrl} target="_blank" rel="noreferrer" />}
            >
              <IconExternalLink />
              View the docs
            </Button>
          </CardAction>
        </CardHeader>
      </Card>
    </div>
  );
}

export const OnboardingPanel = OnboardingPanelBlock;

/** Original design by Gustavo Fior (@gustavo-fior), co-founder Abdul Haidar and Foglamp Labs.
 * Adapted from foglamp-labs/foglamp apps/web/src/app/(app)/agents/[name]/agent-detail-client.tsx under Apache-2.0. */
"use client";

import { Badge } from "../../ui/badge";
import { Button } from "../../ui/button";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "../../ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "../../ui/table";
import {
  IconAlertTriangle,
  IconAlertTriangleFilled,
  IconArrowUpRight,
  IconBoltFilled,
  IconChartAreaFilled,
  IconClockFilled,
  IconCoinFilled,
  IconGhostFilled,
  IconSitemapFilled,
  IconTool,
  IconAffiliateFilled,
} from "@tabler/icons-react";
import { FoglampLink as Link } from "../../lib/link-context";
import { Fragment, useEffect, useMemo, useRef, useState } from "react";

import { AgentIcon } from "../../widgets/leaf/agent-icon";
import { DRAWER_BUTTON_CLASS } from "../../ui/button-styles";
import { CostBreakdownView } from "../../widgets/cost-breakdown";
import {
  PaginationFooter,
  SortableHead,
  useTableSort,
} from "../../widgets/data-table";
import { HeatCell } from "../../widgets/heat-cell";
import {
  useDelayedLoading,
  useEntranceOnce,
  useSkeletonShown,
} from "../../hooks/use-app-hooks";
import { navItem } from "../../widgets/nav";
import { ClampedBody, Prose } from "../../widgets/payload-view";
import { PromptVersionChip } from "../../widgets/prompt-version-chip";
import { PromptVersionsCard } from "../../widgets/prompt-versions-card";
import {
  type FlowNode,
  NodeFlow,
  NodeFlowSkeleton,
} from "../../widgets/leaf/node-flow";
import {
  EmptyState,
  NoProject,
  PageHeader,
  StatCard,
  TableRowsSkeleton,
} from "../../widgets/page-parts";
import { useProject } from "../../widgets/project-context";
import { useRange } from "../../widgets/range-context";
import { RangeControl } from "../../widgets/range-picker";
import { RelativeTime } from "../../widgets/leaf/relative-time";
import {
  Conversation,
  ConversationSkeleton,
  CustomerValue,
  DrawerColumns,
  DrawerRow,
  ExpandChevron,
  FOCUSED_ROW_CLASS,
  Meta,
  MetaEmpty,
  ModelsValue,
  OPEN_ROW_CLASS,
  SessionButton,
  emptyOutputHint,
} from "../../widgets/run-exchange";
import { spanTypeIcon } from "../../widgets/leaf/span-type";
import { ToolBreakdownView } from "../../widgets/tool-breakdown";
import {
  ChartLegend,
  fillBuckets,
  formatBucketFull,
  makeBucketLabel,
  makeEdgeTick,
  themed,
  thinTicks,
  useFrozen,
  useZoomRange,
} from "../../widgets/trend-charts";
import * as AreaChart from "../../charts/evilcharts/charts/area-chart";
import type { ChartConfig } from "../../charts/evilcharts/ui/chart";
import { ModelLogo } from "../../icons/model-logo";
import {
  formatCost,
  formatCostFixed,
  formatCount,
  formatDateTime,
  formatDuration,
  formatPercent,
  formatSpanDuration,
  formatTokens,
} from "../../lib/format";
import { cn } from "../../lib/utils";


type Percentiles = { p50: number; p95: number; p99: number };
export type AgentTraceRow = { traceId: string; traceName: string | null; userMessage: string | null; workflowName: string | null; spanCount: number; durationMs: number; totalCost: number | null; startTime: string; errorCount: number; totalTokens: number; customerId: string | null; customerName: string | null; customerImageUrl: string | null; models: string[]; sessionId: string | null };
export type AgentTraceSpan = { spanId: string; parentSpanId: string | null; spanType: string; modelId: string | null; name: string; status: string; startTime: string; durationMs: number; systemPrompt: string | null; input: string | null; output: string | null };
export type AgentDetailData = {
 stats: { totalCost: number | null; totalTokens: number; errorCount: number; spanCount: number; llmSpanCount: number; latencyMs: Percentiles } | null;
 series: { bucket: string; spanCount: number; errorCount: number; latencyMs: Percentiles }[];
 traces: AgentTraceRow[]; costQuantiles: number[]; durationQuantiles: number[]; totalTraces: number;
 traceDetails: Record<string, { spans: AgentTraceSpan[]; promptVersion?: {id: string; number: number} | null; agentName?: string | null }>;
 alerts: { id: string; enabled: boolean; threshold: number | null; evalId: string | null; metric: string; filters?: { agentName?: string | null; modelId?: string | null; workflowName?: string | null; metadata?: Record<string, unknown> } | null }[];
 costs: React.ComponentProps<typeof CostBreakdownView>["data"]; tools: React.ComponentProps<typeof ToolBreakdownView>["tools"]; versions: React.ComponentProps<typeof PromptVersionsCard>["versions"];
};
const DEFAULT_DATA: AgentDetailData = { stats: { totalCost: 0.0042, totalTokens: 842, errorCount: 0, spanCount: 3, llmSpanCount: 1, latencyMs: { p50: 1200, p95: 1800, p99: 2000 } }, series: [], traces: [{ traceId: "trace_demo", traceName: "Support request", userMessage: "How can I track my order?", workflowName: "Support", spanCount: 3, durationMs: 1800, totalCost: 0.0042, startTime: "2026-01-01T12:00:00Z", errorCount: 0, totalTokens: 842, customerId: null, customerName: null, customerImageUrl: null, models: ["gpt-4o"], sessionId: null }], costQuantiles: [], durationQuantiles: [], totalTraces: 1, traceDetails: { trace_demo: { spans: [{ spanId: "span_demo", parentSpanId: null, spanType: "agent", modelId: null, name: "Support agent", status: "ok", startTime: "2026-01-01T12:00:00Z", durationMs: 1800, systemPrompt: "Help customers with their orders.", input: "How can I track my order?", output: "Please share your order number." }] } }, alerts: [], costs: [], tools: [], versions: [] };
type TraceRow = AgentTraceRow;

const PAGE_SIZES = [25, 50, 100];

// Skeleton column spec for the loading body rows (see TableRowsSkeleton).
const SKELETON_COLS = [
  { icon: true, w: "w-64" },
  { w: "w-20" },
  { align: "right", w: "w-8" },
  { align: "right", w: "w-12" },
  { align: "right", w: "w-14" },
  { align: "right", w: "w-16" },
] as const;

type TraceSortKey = "when" | "duration" | "tokens" | "spans" | "cost";

const volumeConfig = {
  spans: { label: "Spans", colors: themed("var(--chart-2)") },
  errors: { label: "Errored", colors: themed("var(--destructive)") },
} satisfies ChartConfig;

const latencyConfig = {
  // neutral-800 on light, neutral-200 on dark — matches the Overview latency chart
  p50: { label: "p50", colors: { light: ["#262626"], dark: ["#e5e5e5"] } },
  p95: { label: "p95", colors: themed("#0090FD") },
  p99: { label: "p99", colors: themed("#FF5513") },
} satisfies ChartConfig;

function stepIcon(
  spanType: string,
  modelId: string | null,
  name: string | null,
) {
  if (spanType === "llm" && modelId)
    return <ModelLogo modelId={modelId} className="size-3.25" />;
  if (spanType === "agent")
    return <AgentIcon name={name} className="size-3.25" />;
  if (spanType === "tool")
    return (
      <IconTool className="size-3 shrink-0 fill-current stroke-1 text-blue-500 mb-px" />
    );
  const Icon = spanTypeIcon(spanType);
  return <Icon className="size-3.25 text-muted-foreground" />;
}

export function AgentDetailInspectorBlock({ agentName = "Support agent", data = DEFAULT_DATA, isLoading = false, isUpdating = false, initialTrace, onNavigate, onTraceChange }: { agentName?: string; data?: AgentDetailData; isLoading?: boolean; isUpdating?: boolean; initialTrace?: string | null; onNavigate?: (href: string) => void; onTraceChange?: (id: string | null) => void }) {
  const entrance = useEntranceOnce();
  const { projectId } = useProject();
  const { range, setRange } = useRange();
  // A `?trace=` deep link focuses one trace: its row opens and is tinted.
  const focusTrace = initialTrace ?? null;
  // Which trace row is expanded (steps + input/output drawer). Mirrors `?trace=`
  // so an open drawer is deep-linkable.
  const [expanded, setExpanded] = useState<string | null>(focusTrace);
  // The row the page was *opened on* (deep link) gets the focused tint and a
  // scroll-into-view; rows the user expands themselves are plain card, like
  // the evals table. Cleared on the first toggle so the tint doesn't follow
  // the `?trace=` mirror around.
  const [deepLinked, setDeepLinked] = useState<string | null>(focusTrace);
  const focusRef = useRef<HTMLTableRowElement>(null);
  useEffect(() => {
    if (initialTrace !== undefined) return;
    const id = new URLSearchParams(window.location.search).get("trace");
    setExpanded(id);
    setDeepLinked(id);
  }, [initialTrace]);

  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(PAGE_SIZES[0]);
  // Selected series for each trend chart, driven by the header legends.
  const [volumeSelected, setVolumeSelected] = useState<string | null>(null);
  const [latencySelected, setLatencySelected] = useState<string | null>(null);
  const { sort, toggle } = useTableSort<TraceSortKey>();

  const zoom = useZoomRange();
  const detail = { data: { stats: data.stats }, isLoading };
  const series = { data: data.series, isLoading, isPlaceholderData: isUpdating };
  const alerts = { data: data.alerts };
  const latencyThresholds = useMemo(
    () =>
      (alerts.data ?? []).filter(
        (r) =>
          r.enabled &&
          r.threshold != null &&
          !r.evalId &&
          (r.metric === "latency_p50" ||
            r.metric === "latency_p95" ||
            r.metric === "latency_p99") &&
          (!r.filters?.agentName || r.filters.agentName === agentName) &&
          !r.filters?.modelId &&
          !r.filters?.workflowName &&
          Object.keys(r.filters?.metadata ?? {}).length === 0,
      ),
    [alerts.data, agentName],
  );

  const sortedTraces = [...data.traces];
  if (sort) {
    const value = (row: AgentTraceRow) => sort.key === "when" ? Date.parse(row.startTime) : sort.key === "duration" ? row.durationMs : sort.key === "tokens" ? row.totalTokens : sort.key === "spans" ? row.spanCount : row.totalCost ?? 0;
    sortedTraces.sort((a, b) => (value(a) - value(b)) * (sort.dir === "asc" ? 1 : -1));
  }
  const traces = { data: { traces: sortedTraces.slice(page * pageSize, (page + 1) * pageSize), costQuantiles: data.costQuantiles, durationQuantiles: data.durationQuantiles, summary: { traceCount: data.totalTraces } }, isLoading, isFetching: isUpdating };

  // Reset paging + any open drawer when the query that defines the result set
  // changes (skipping mount, so a deep-linked drawer survives the first render).
  const mounted = useRef(false);
  // biome-ignore lint/correctness/useExhaustiveDependencies: reset on filter changes only
  useEffect(() => {
    if (!mounted.current) {
      mounted.current = true;
      return;
    }
    setPage(0);
    setExpanded(null);
  }, [range, projectId, sort]);

  const traceRows = traces.data?.traces ?? [];
  // Global 20/40/60/80th-percentile thresholds for the heat-tinted cells,
  // computed server-side over the whole filtered window (not just this page).
  const costQuantiles = traces.data?.costQuantiles ?? [];
  const durationQuantiles = traces.data?.durationQuantiles ?? [];

  // Toggle a row's drawer and mirror it in the URL (`?trace=`), so the open
  // trace can be shared and survives a reload.
  const toggleTrace = (id: string) => {
    const next = expanded === id ? null : id;
    setExpanded(next);
    setDeepLinked(null);
    if (onTraceChange) onTraceChange(next);
    else {
      const url = new URL(window.location.href);
      if (next) url.searchParams.set("trace", next);
      else url.searchParams.delete("trace");
      window.history.replaceState(window.history.state, "", url);
    }
  };
  // Once the deep-linked trace is on the loaded page, scroll it into view.
  // biome-ignore lint/correctness/useExhaustiveDependencies: re-run as traces load
  useEffect(() => {
    if (deepLinked && focusRef.current) {
      focusRef.current.scrollIntoView({ block: "center", behavior: "smooth" });
    }
  }, [deepLinked, traces.data]);
  // Delay the skeleton so fast loads don't flash it (see useDelayedLoading).
  const showTracesSkeleton = useDelayedLoading(traces.isLoading);
  // Latch for the entrance fade: the traces table only fades in if this slot
  // never painted a skeleton first (see useSkeletonShown).
  const tracesSkeletonShown = useSkeletonShown(showTracesSkeleton);

  // While a range change refetches, the trend charts hold the previous view —
  // the rows *and* the window they were fetched for, so fill, ticks, and label
  // format stay mutually consistent — dimmed (isUpdating), then swap to the
  // fresh view in one transition.
  const chartsStale = series.isPlaceholderData;
  const chartView = useFrozen(
    { series: series.data, from: range.from, to: range.to },
    chartsStale,
  );
  const chartWindowMs = chartView.to.getTime() - chartView.from.getTime();
  const bucketLabel = useMemo(
    () => makeBucketLabel(chartWindowMs),
    [chartWindowMs],
  );
  const edgeTick = useMemo(() => makeEdgeTick(bucketLabel), [bucketLabel]);
  // Keep the raw bucket as the x value (formatted on the axis) so we can thin
  // the ticks and edge-anchor the first/last labels. Zero-filled so an agent's
  // quiet stretches keep their width on the x-axis.
  const seriesData = useMemo(
    () =>
      fillBuckets(
        (chartView.series ?? []).map((r) => ({
          bucket: r.bucket,
          spans: r.spanCount,
          errors: r.errorCount,
          p50: r.latencyMs.p50,
          p95: r.latencyMs.p95,
          p99: r.latencyMs.p99,
        })),
        chartView.from,
        chartView.to,
        (bucket) => ({ bucket, spans: 0, errors: 0, p50: 0, p95: 0, p99: 0 }),
      ),
    [chartView],
  );
  // Latency as a stacked *band* chart: each area plots the delta to the band
  // below it (p50, p95−p50, p99−p95), so its gradient fill is bounded between two
  // percentile lines instead of bleeding down to the axis. The stack tops land
  // exactly on p50/p95/p99; the absolutes ride along for the tooltip.
  const latencyData = useMemo(
    () =>
      seriesData.map((r) => ({
        bucket: r.bucket,
        p50: r.p50,
        p95: Math.max(0, r.p95 - r.p50),
        p99: Math.max(0, r.p99 - r.p95),
        p50Abs: r.p50,
        p95Abs: r.p95,
        p99Abs: r.p99,
      })),
    [seriesData],
  );

  const seriesTicks = useMemo(
    () =>
      thinTicks(
        seriesData.map((d) => d.bucket),
        bucketLabel,
      ),
    [seriesData, bucketLabel],
  );

  const back = navItem("/agents");

  if (!projectId) {
    return (
      <>
        <PageHeader
          title={agentName}
          titleLeading={<AgentIcon name={agentName} className="size-4.5" />}
          back={back}
        />
        <NoProject />
      </>
    );
  }

  const stats = detail.data?.stats ?? null;
  const errorRate =
    stats && stats.spanCount > 0 ? stats.errorCount / stats.spanCount : null;

  const totalTraces = traces.data?.summary.traceCount ?? 0;
  // No activity for this agent at all (not just filtered away). Wait for the
  // stats so a slow rollup doesn't flash the empty state before they land.
  const noData = !detail.isLoading && (stats === null || stats.spanCount === 0);
  const seriesLoading = series.isLoading;

  return (
    <>
      <div className={cn(entrance && "page-fade-in")}>
        <PageHeader
          title={agentName}
          titleLeading={<AgentIcon name={agentName} className="size-4.5" />}
          back={back}
          actions={<RangeControl value={range} onChange={setRange} />}
        />
      </div>

      {noData ? (
        <div className={cn(entrance && "page-fade-in", "px-8")}>
          <EmptyState
            icon={IconGhostFilled}
            title="No activity in this range"
            description="Try widening the time range, or this agent has no traces yet."
          />
        </div>
      ) : (
        <>
          {/* Stat strip — totals over all spans in the window. */}
          <section
            className={cn(
              "grid grid-cols-2 gap-4 md:grid-cols-4 px-8 mt-1",
              entrance && "page-fade-in",
            )}
          >
            <StatCard
              icon={IconCoinFilled}
              iconClassName="text-amber-400 dark:text-yellow-500"
              size="sm"
              label="Total cost"
              value={stats?.totalCost ?? "—"}
              formatValue={(n) => formatCostFixed(n, 4)}
              hint={`${formatTokens(stats?.totalTokens ?? 0)} tokens`}
            />
            <StatCard
              icon={IconAlertTriangleFilled}
              iconClassName="text-red-500/90 dark:text-red-600/95 mt-px"
              size="sm"
              label="Error rate"
              value={errorRate ?? "—"}
              formatValue={formatPercent}
              hint={`${formatCount(stats?.errorCount ?? 0)} errors`}
            />
            <StatCard
              icon={IconClockFilled}
              iconClassName="text-sky-400 dark:text-sky-500"
              size="sm"
              label="p95 latency"
              value={stats?.latencyMs.p95 ?? 0}
              formatValue={formatDuration}
              hint={`p50 ${formatDuration(stats?.latencyMs.p50 ?? 0)}`}
            />

            <StatCard
              icon={IconBoltFilled}
              iconClassName="text-orange-500 dark:text-orange-500"
              size="sm"
              label="Spans"
              value={stats?.spanCount ?? 0}
              formatValue={formatCount}
              hint={`${formatCount(stats?.llmSpanCount ?? 0)} LLM`}
            />
          </section>

          {/* Trend: span volume + LLM latency percentiles over the window. */}
          <section className="grid gap-4 lg:grid-cols-2 px-8">
            <Card size="sm" className={cn(entrance && "page-fade-in")}>
              <CardHeader className="flex flex-row items-center justify-between gap-4">
                <CardTitle>Spans & errors</CardTitle>
                <ChartLegend
                  config={volumeConfig}
                  selected={volumeSelected}
                  onSelect={setVolumeSelected}
                />
              </CardHeader>
              <CardContent className="mt-2">
                {!seriesLoading && seriesData.length === 0 ? (
                  <EmptyState
                    icon={IconChartAreaFilled}
                    title="No data in this range"
                  />
                ) : (
                  <AreaChart.EvilAreaChart
                    config={volumeConfig}
                    data={seriesData}
                    isLoading={seriesLoading}
                    isUpdating={chartsStale}
                    xDataKey="bucket"
                    syncId="agent-trends"
                    onZoomSelect={zoom.zoomTo}
                    onZoomReset={zoom.reset}
                    selectedDataKey={volumeSelected}
                    onSelectionChange={setVolumeSelected}
                    className="h-55 w-full"
                    chartProps={{
                      // left: 2 (vs Recharts' default 5) tucks the auto-width
                      // y-axis labels closer to the card content edge.
                      margin: { top: 5, right: 5, bottom: 5, left: 2 },
                    }}
                  >
                    <AreaChart.Grid />
                    <AreaChart.XAxis
                      dataKey="bucket"
                      ticks={seriesTicks}
                      tickFormatter={bucketLabel}
                      interval={0}
                      tick={edgeTick}
                    />
                    <AreaChart.YAxis
                      allowDecimals={false}
                      tickFormatter={(v) => formatCount(Number(v))}
                    />
                    <AreaChart.Tooltip
                      labelFormatter={(v) => formatBucketFull(String(v))}
                    />
                    <AreaChart.Area dataKey="spans" strokeVariant="solid" />
                    <AreaChart.Area
                      dataKey="errors"
                      strokeVariant="solid"
                      variant="lines"
                    />
                  </AreaChart.EvilAreaChart>
                )}
              </CardContent>
            </Card>

            <Card size="sm" className={cn(entrance && "page-fade-in")}>
              <CardHeader className="flex flex-row items-center justify-between gap-4">
                <CardTitle>Latency</CardTitle>
                <ChartLegend
                  config={latencyConfig}
                  selected={latencySelected}
                  onSelect={setLatencySelected}
                />
              </CardHeader>
              <CardContent className="mt-2">
                {!seriesLoading && seriesData.length === 0 ? (
                  <EmptyState
                    icon={IconChartAreaFilled}
                    title="No data in this range"
                  />
                ) : (
                  <AreaChart.EvilAreaChart
                    config={latencyConfig}
                    data={latencyData}
                    isLoading={seriesLoading}
                    isUpdating={chartsStale}
                    xDataKey="bucket"
                    syncId="agent-trends"
                    onZoomSelect={zoom.zoomTo}
                    onZoomReset={zoom.reset}
                    stackType="stacked"
                    selectedDataKey={latencySelected}
                    onSelectionChange={setLatencySelected}
                    className="h-55 w-full"
                    chartProps={{
                      // left: 2 (vs Recharts' default 5) tucks the auto-width
                      // y-axis labels closer to the card content edge.
                      margin: { top: 5, right: 5, bottom: 5, left: 2 },
                    }}
                  >
                    <AreaChart.Grid />
                    <AreaChart.XAxis
                      dataKey="bucket"
                      ticks={seriesTicks}
                      tickFormatter={bucketLabel}
                      interval={0}
                      tick={edgeTick}
                    />
                    <AreaChart.YAxis
                      tickFormatter={(v) => formatDuration(Number(v))}
                    />
                    <AreaChart.Tooltip
                      labelFormatter={(v) => formatBucketFull(String(v))}
                      valueFormatter={(_v, key, row) =>
                        formatDuration(Number(row[`${key}Abs`] ?? _v))
                      }
                      reverse
                    />
                    {/* Stacked deltas (see latencyData): draw bottom band → top
                        so the stack reads p50, then p95−p50, then p99−p95. */}
                    <AreaChart.Area dataKey="p50" strokeVariant="solid" />
                    <AreaChart.Area dataKey="p95" strokeVariant="solid" />
                    <AreaChart.Area dataKey="p99" strokeVariant="solid" />
                    {latencyThresholds.map((r) => (
                      <AreaChart.Threshold
                        key={r.id}
                        value={Number(r.threshold)}
                        label={`${r.metric.slice("latency_".length)} alert`}
                      />
                    ))}
                  </AreaChart.EvilAreaChart>
                )}
              </CardContent>
            </Card>
          </section>

          {/* Where this agent's spend and time go: cost per price dimension
              over the window, beside the per-tool runtime breakdown. */}
          <section className="grid gap-4 lg:grid-cols-2 px-8">
            <CostBreakdownView
              data={data.costs}
              range={range}
              syncId="agent-trends"
              onZoomSelect={zoom.zoomTo}
              onZoomReset={zoom.reset}
              className={cn(entrance && "page-fade-in")}
            />
            <ToolBreakdownView
              tools={data.tools}
              className={cn(entrance && "page-fade-in")}
            />
          </section>

          {/* The system prompts this agent has run with, grouped into
              versions by the prompt job. */}
          <section className="px-8">
            <PromptVersionsCard
              versions={data.versions}
              loading={isLoading}
              skeleton={isLoading}
              className={cn(entrance && "page-fade-in")}
            />
          </section>

          {/* Traces table — click a row to open its steps + exchange. */}
          <div className="flex flex-col gap-3 mt-4">
            {!traces.isLoading && traceRows.length === 0 ? (
              <div
                className={cn(
                  entrance && !tracesSkeletonShown && "page-fade-in",
                  "px-8",
                )}
              >
                <EmptyState
                  icon={IconGhostFilled}
                  title="No traces in this range"
                  description="Try widening the time range."
                />
              </div>
            ) : (
              // Table mounted while loading (skeleton rows in the body) so the
              // swap to data doesn't reflow; footer flush with the last row.
              <div
                className={cn(
                  "flex flex-col",
                  entrance && !tracesSkeletonShown && "page-fade-in",
                )}
              >
                {/* pr-11 (not the default pr-9): the range picker lives in the
                    page header here (px-8) rather than a toolbar (pr-6), so
                    the last column needs 8px more to line up with its chevron
                    the way the list pages do. */}
                <Table
                  className="table-fixed [&_th:last-child]:pr-11 [&_td:last-child]:pr-11"
                  stickyHeader
                >
                  <TableHeader>
                    <TableRow>
                      <TableHead>Trace</TableHead>
                      <TableHead className="w-44">Workflow</TableHead>
                      <SortableHead
                        sortKey="spans"
                        sort={sort}
                        onSort={toggle}
                        align="right"
                        className="w-20"
                      >
                        Spans
                      </SortableHead>
                      <SortableHead
                        sortKey="duration"
                        sort={sort}
                        onSort={toggle}
                        align="right"
                        className="w-28"
                      >
                        Duration
                      </SortableHead>
                      <SortableHead
                        sortKey="cost"
                        sort={sort}
                        onSort={toggle}
                        align="right"
                        className="w-28"
                      >
                        Cost
                      </SortableHead>
                      <SortableHead
                        sortKey="when"
                        sort={sort}
                        onSort={toggle}
                        align="right"
                        className="w-32"
                      >
                        When
                      </SortableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {traces.isLoading ? (
                      showTracesSkeleton ? (
                        <TableRowsSkeleton cols={SKELETON_COLS} />
                      ) : null
                    ) : (
                      traceRows.map((t) => {
                        const isOpen = expanded === t.traceId;
                        const isFocused = t.traceId === deepLinked;
                        return (
                          <Fragment key={t.traceId}>
                            <TableRow
                              ref={isFocused ? focusRef : undefined}
                              interactive
                              aria-expanded={isOpen}
