                              className={cn(
                                "group",
                                isOpen && OPEN_ROW_CLASS,
                                isFocused && FOCUSED_ROW_CLASS,
                              )}
                            >
                              {/* Content-first, like the traces list: the
                                  trace's user message, then its name, then
