                                <div className="flex items-center gap-2">
                                  <ExpandChevron open={isOpen} />
                                  <span className="truncate">
                                    {t.userMessage ?? t.traceName ?? (
                                      <span className="font-mono text-xs text-muted-foreground">
                                        {t.traceId}
