        <div className="size-6 shrink-0 animate-pulse rounded-full bg-muted" />
        <div className="flex min-w-0 flex-1 flex-col gap-2 px-1 pt-1">
          {Array.from({ length: lines }, (_, i) => (
            <Skeleton
              key={i}
              className={cn(
                "h-3.5",
                i === lines - 1 ? "w-2/3" : i % 2 ? "w-11/12" : "w-full",
              )}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

