  const { projectId } = useProject();
  const { range, setRange } = useRange();
  const input = useMemo(() => suppliedTraces ?? DEFAULT_TRACES.map((trace, i) => ({ ...trace, startTime: new Date(range.from.getTime() + (range.to.getTime() - range.from.getTime()) * (0.8 - i * 0.2)).toISOString() })), [suppliedTraces, range]);

  // Filters + sorting (applied server-side across the full result set) live in
  // the URL so the view survives reload/back and can be shared.
  const [params, patchParams] = useUrlFilters({
    agent: "",
    prompt: "",
    workflow: "",
    customer: "",
    model: "",
    metaKey: "",
    metaValue: "",
    errors: "",
    sort: "",
    page: "1",
    size: "25",
  });
  const { agent, prompt, workflow, customer, model, metaKey, metaValue, errors, sort: sortParam, page: pageParam, size } = params;
  useEffect(() => {
    onFiltersChange?.({ agent, prompt, workflow, customer, model, metaKey, metaValue, errors, sort: sortParam, page: pageParam, size });
  }, [onFiltersChange, agent, prompt, workflow, customer, model, metaKey, metaValue, errors, sortParam, pageParam, size]);
  const agentFilter = params.agent;
  // Prompt version (an id from agents.promptVersions) — only meaningful
  // together with the agent it belongs to.
  const promptFilter = params.prompt;
  const workflowFilter = params.workflow;
  const customerFilter = params.customer;
  const modelFilter = params.model;
  // Metadata: the key alone pins its value as a table column; key + value
  // filters the trace set.
  const metaKeyFilter = params.metaKey;
  const metaValueFilter = params.metaValue;
  const errorsOnly = params.errors === "1";
  const sort = parseSortParam(params.sort, TRACE_SORT_KEYS);
  const toggle = (key: TraceSortKey) =>
    patchParams({ sort: cycleSortParam(sort, key) });
  const page = Math.max(0, (Number.parseInt(params.page, 10) || 1) - 1);
  const setPage = (p: number) => patchParams({ page: String(p + 1) });
  const pageSize = PAGE_SIZES.includes(Number(params.size))
    ? Number(params.size)
    : 25;
  const hasFilters = !!(
    agentFilter ||
    promptFilter ||
    workflowFilter ||
    customerFilter ||
    modelFilter ||
    metaKeyFilter ||
    errorsOnly
  );

  // Secondary filters (workflow/customer/metadata/prompt version) stay out of
  // the toolbar until applied via the "+ Filter" menu — `added` tracks the
  // ones summoned this session so an empty select can sit open before a value
  // is picked.
  const [added, setAdded] = useState<Set<SecondaryFilter>>(() => new Set());
  const addFilter = (k: SecondaryFilter) =>
    setAdded((s) => new Set(s).add(k));
  const removeFilter = (k: SecondaryFilter) =>
    setAdded((s) => {
      const next = new Set(s);
      next.delete(k);
      return next;
    });
  // Filter/sort changes reset the page inside patchParams; project and range
  // changes happen outside it, so reset explicitly (skipping mount, which
  // would wipe the page from a shared/reloaded URL).
  const mounted = useRef(false);
  // biome-ignore lint/correctness/useExhaustiveDependencies: page reset on project/range change only
  useEffect(() => {
    if (!mounted.current) {
      mounted.current = true;
      return;
    }
    patchParams({ page: "1" });
  }, [projectId, range]);

  const inRange = input.filter(t => { const time = new Date(t.startTime).getTime(); return time >= range.from.getTime() && time <= range.to.getTime(); });
  const agentsList = { data: [...new Set(inRange.flatMap(t => t.agentName ? [t.agentName] : []))] };
  const workflowsList = { data: [...new Set(inRange.flatMap(t => t.workflowName ? [t.workflowName] : []))] };
  const customersList = { data: { customers: [...new Map(inRange.filter(t => t.customerId).map(t => [t.customerId, { customerId: t.customerId, customerName: t.customerName, customerImageUrl: t.customerImageUrl }])).values()] } };
  const modelsList = { data: [...new Set(inRange.flatMap(t => t.models))].map(modelId => ({ modelId })) };
  const metaKeysList = { data: [...new Set(inRange.flatMap(t => Object.keys(t.metadata ?? {})))] };
  const metaValuesList = { data: { values: [...new Set(inRange.flatMap(t => t.metadata?.[metaKeyFilter] ? [t.metadata[metaKeyFilter]] : []))], truncated: false } };
  const promptOptions = versions.filter(v => !agentFilter || v.agentName === agentFilter).slice().reverse().map(v => ({ value: v.id, label: `${agentFilter ? "" : `${v.agentName} · `}v${v.number}`, hint: v.current ? "current" : undefined, icon: PromptVersionIcon }));
  const promptAgentOf = (id: string) => versions.find(v => v.id === id)?.agentName ?? "";
  const filtered = inRange.filter(t => (!agentFilter || t.agentName === agentFilter) && (!promptFilter || t.promptVersionId === promptFilter) && (!workflowFilter || t.workflowName === workflowFilter) && (!customerFilter || t.customerId === customerFilter) && (!modelFilter || t.models.includes(modelFilter)) && (!metaValueFilter || t.metadata?.[metaKeyFilter] === metaValueFilter) && (!errorsOnly || t.errorCount > 0));
  const value = (t: TraceExplorerRow, key: TraceSortKey) => key === "when" ? new Date(t.startTime).getTime() : key === "cost" ? t.totalCost ?? 0 : key === "duration" ? t.durationMs : key === "tokens" ? t.totalTokens : t.spanCount;
  const sorted = filtered.slice().sort((a, b) => sort ? (value(a, sort.key) - value(b, sort.key)) * (sort.dir === "asc" ? 1 : -1) : value(b, "when") - value(a, "when"));
  const quantiles = (values: number[]) => { const xs = values.filter(v => v > 0).sort((a,b) => a-b); return xs.length ? [0.2, 0.4, 0.6, 0.8].map(q => xs[Math.min(xs.length - 1, Math.floor(q * xs.length))]!) : []; };
  const traces = { isLoading, isFetching, data: { traces: sorted.slice(page * pageSize, (page + 1) * pageSize).map(t => ({ ...t, metadataValue: t.metadata?.[metaKeyFilter] ?? null })), costQuantiles: quantiles(filtered.map(t => t.totalCost ?? 0)), durationQuantiles: quantiles(filtered.map(t => t.durationMs)), summary: { traceCount: filtered.length } } };
  // Delay the skeleton so fast loads don't flash it (see useDelayedLoading).
  // Only the table body waits on data — the toolbar and column headers are
  // static chrome and paint immediately.
  const showSkeleton = useDelayedLoading(traces.isLoading);

  if (!projectId) {
    return (
      <>
        <PageHeader
          title="Traces"
          icon={navItem("/traces")?.icon}
          iconClassName={navItem("/traces")?.iconClassName}
        />
        <NoProject />
      </>
    );
  }

  const rows = traces.data?.traces ?? [];
  const costQuantiles = traces.data?.costQuantiles ?? [];
  const durationQuantiles = traces.data?.durationQuantiles ?? [];
  const summary = traces.data?.summary;
  // Secondary filters surface once applied (URL) or summoned via "+ Filter".
  const showWorkflow = added.has("workflow") || !!workflowFilter;
  const showCustomer = added.has("customer") || !!customerFilter;
  const showMeta = added.has("meta") || !!metaKeyFilter;
  // Prompt version is offered once any agent has inferred versions.
  const canPrompt = promptOptions.length > 0;
  const showPrompt = added.has("prompt") || !!promptFilter;
  const canAddFilter =
    !showWorkflow || !showCustomer || !showMeta || (canPrompt && !showPrompt);
  const agentOptions = (agentsList.data ?? []).map((name) => ({
    value: name,
    label: name,
    icon: (p: { className?: string }) => (
      <AgentIcon name={name} className={p.className} />
    ),
  }));
  const workflowOptions = (workflowsList.data ?? []).map((name) => ({
    value: name,
    label: name,
    icon: WorkflowIconFilled,
  }));
  const metaKeyOptions = (metaKeysList.data ?? []).map((key) => ({
    value: key,
    label: key,
    icon: MetaValueIcon,
  }));
  const metaValueOptions = (metaValuesList.data?.values ?? []).map((v) => ({
    value: v,
    label: v,
    icon: MetaValueIcon,
  }));
  const customerOptions = (customersList.data?.customers ?? [])
    .filter((c): c is typeof c & { customerId: string } => !!c.customerId)
    .map((c) => ({
      value: c.customerId,
      label: c.customerName ?? c.customerId,
      icon: (p: { className?: string }) => (
        <CustomerAvatar
          customerId={c.customerId}
          customerName={c.customerName}
          imageUrl={c.customerImageUrl}
          className={p.className}
        />
      ),
    }));
  const modelOptions = (modelsList.data ?? [])
    .filter((m) => m.modelId !== "(unknown)")
    .map((m) => ({
      value: m.modelId,
      label: formatModelName(m.modelId),
      icon: (p: { className?: string }) => (
        <ModelLogo modelId={m.modelId} className={p.className} />
      ),
    }));

  return (
    <>
      {/* Wrapped here (not inside TracesHeader) so the copy rendered by
          loading.tsx stays unanimated — only the page's own header fades. */}
      <div className={cn(entrance && "page-fade-in")}>
        <RouteHeader href="/traces" title="Traces" />
      </div>
      {/* Toolbar and table chrome always render — even for an empty result —
			    so the range picker and filters stay reachable (an empty range needs
			    the range picker to escape). The empty states swap in for the table
			    only; the body rows wait on the query (skeleton rows below). */}
      <div
        className={cn("flex flex-col gap-4 mt-1", entrance && "page-fade-in")}
      >
        <Toolbar
          trailing={
            <>
              <RangeControl value={range} onChange={setRange} />
            </>
          }
        >
          {/* Hero filters stay inline; the rest live behind "+ Filter" and
                only occupy the toolbar while applied (or freshly summoned). */}
          <FilterSelect
            value={agentFilter}
            onChange={(v) => {
              patchParams({ agent: v, prompt: "" });
              // Versions belong to one agent; a summoned prompt select
              // doesn't carry over to the next.
              removeFilter("prompt");
            }}
            allLabel="Any agent"
            icon={IconGhost}
            options={agentOptions}
          />
          <FilterSelect
            value={modelFilter}
            onChange={(v) => patchParams({ model: v })}
            allLabel="Any model"
            icon={IconCpu}
            options={modelOptions}
          />

          <ToggleChip
            active={errorsOnly}
            onClick={() => patchParams({ errors: errorsOnly ? "" : "1" })}
          >
            <IconAlertTriangle className="size-3.5" />
            Errors only
          </ToggleChip>

          {showWorkflow && (
            <FilterSelect
              value={workflowFilter}
              onChange={(v) => {
                patchParams({ workflow: v });
                // Resetting to "Any" dismisses a summoned filter entirely.
                if (!v) removeFilter("workflow");
              }}
              allLabel="Any workflow"
              icon={IconSitemap}
              options={workflowOptions}
            />
          )}
          {showCustomer && (
            <FilterSelect
              value={customerFilter}
              onChange={(v) => {
                patchParams({ customer: v });
                if (!v) removeFilter("customer");
              }}
              allLabel="Any customer"
              icon={IconUser}
              options={customerOptions}
            />
          )}
          {/* Metadata: picking a key pins its value as a column and reveals
                the value picker; picking a value filters the trace set. */}
          {showMeta && (
            <FilterSelect
              value={metaKeyFilter}
              onChange={(v) => {
                patchParams({ metaKey: v, metaValue: "" });
                if (!v) removeFilter("meta");
              }}
              allLabel="Any metadata"
              icon={IconTag}
              options={metaKeyOptions}
            />
          )}
          {showMeta && metaKeyFilter && (
            <FilterSelect
              value={metaValueFilter}
              onChange={(v) => patchParams({ metaValue: v })}
              allLabel={`Any ${metaKeyFilter}`}
              icon={IconTag}
              options={metaValueOptions}
              allowFreeText={metaValuesList.data?.truncated ?? false}
            />
          )}
          {showPrompt && (
            <FilterSelect
              value={promptFilter}
              onChange={(v) => {
                // A version belongs to one agent: picking it without an agent
                // filter narrows to that agent as well, so the two agree.
                patchParams({
                  prompt: v,
                  agent: agentFilter || (v ? promptAgentOf(v) : ""),
                });
                if (!v) removeFilter("prompt");
              }}
              allLabel="Any prompt version"
              icon={IconFileHorizontal}
              options={promptOptions}
            />
          )}
          {canAddFilter && (
            <AddFilterMenu
              showWorkflow={showWorkflow}
              showCustomer={showCustomer}
              showMeta={showMeta}
              showPrompt={showPrompt}
              canPrompt={canPrompt}
              onAdd={addFilter}
            />
          )}
          <ClearFiltersButton
            show={hasFilters}
            onClick={() => {
              patchParams({
                agent: "",
                prompt: "",
                workflow: "",
                customer: "",
                model: "",
                metaKey: "",
                metaValue: "",
                errors: "",
              });
              setAdded(new Set());
            }}
          />
        </Toolbar>

        {!traces.isLoading && rows.length === 0 && page === 0 ? (
          <div className="mt-2 px-8">
            {hasFilters ? (
              <EmptyState
                icon={IconAffiliateFilled}
                title="No matching traces"
                description="Try a different search or clearing filters."
              />
            ) : (
              <EmptyState
                icon={IconAffiliateFilled}
                title="No traces yet"
                description="Run an instrumented call to see traces here."
              />
            )}
          </div>
        ) : (
          // Single column with no gap so the pagination footer's top border
          // sits flush against the table's last row.
          <div className="flex flex-col -mt-2">
            <TooltipProvider delay={150}>
              {/* Fixed layout: column widths come from the header's w-* classes,
								    so the skeleton→data swap can't re-measure and shift columns. */}
              <Table className="table-fixed min-w-5xl" stickyHeader>
                <TableHeader>
                  <TableRow>
                    <TableHead>Trace</TableHead>
                    {metaKeyFilter && (
                      <TableHead className="w-40">
                        <span className="inline-flex items-center gap-1.5">
                          <IconTagFilled className="size-3.5 text-fuchsia-500" />
                          {metaKeyFilter}
                        </span>
                      </TableHead>
                    )}
                    <SortableHead
                      sortKey="spans"
                      sort={sort}
                      onSort={toggle}
                      align="right"
                      className="w-28"
                    >
                      Spans
                    </SortableHead>
                    <SortableHead
                      sortKey="tokens"
                      sort={sort}
                      onSort={toggle}
                      align="right"
                      className="w-30"
                    >
                      Tokens
                    </SortableHead>
                    <SortableHead
                      sortKey="duration"
                      sort={sort}
                      onSort={toggle}
                      align="right"
                      className="w-32"
                    >
                      Duration
                    </SortableHead>
                    <SortableHead
                      sortKey="cost"
                      sort={sort}
                      onSort={toggle}
                      align="right"
                      className="w-38"
                    >
                      Cost
                    </SortableHead>
                    <SortableHead
                      sortKey="when"
                      sort={sort}
                      onSort={toggle}
                      align="right"
                      className="w-36"
                    >
                      When
                    </SortableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {traces.isLoading ? (
                    showSkeleton ? (
                      // The meta column only exists while a meta filter is set.
                      <TableRowsSkeleton
                        cols={
                          metaKeyFilter
                            ? [
                                SKELETON_COLS[0],
                                { w: "w-24" },
                                ...SKELETON_COLS.slice(1),
                              ]
                            : SKELETON_COLS
                        }
                        rowHeight="h-16"
                      />
                    ) : null
                  ) : (
                    rows.map((t) => (
                      <TableRow
                        key={t.traceId}
                        interactive
                        onClick={() => onTraceSelect ? onTraceSelect(t.traceId) : window.location.assign(`/traces/${encodeURIComponent(t.traceId)}`)}
                        onKeyDown={(event) => { if (event.key === "Enter") onTraceSelect ? onTraceSelect(t.traceId) : window.location.assign(`/traces/${encodeURIComponent(t.traceId)}`); }}
                        tabIndex={0}
                      >
                        <TableCell className="h-16">
                          <div className="min-w-0 flex justify-between items-center">
                            {/* min-w-0: flex items refuse to shrink below their content
														    by default, so without it the meta line overflows into the
														    next column instead of truncating. */}
                            <div className="min-w-0 flex flex-col gap-1">
                              <div className="flex items-center gap-2">
                                {/* Content-first title: the trace's user
                                    message, then an explicit trace name (the
                                    SDK falls back to the agent name, which is
                                    just noise repeated down the column), then
                                    the raw id. */}
                                <span className="truncate text-[14px]">
                                  {t.userMessage ??
                                    (t.traceName && t.traceName !== t.agentName
                                      ? t.traceName
                                      : null) ??
                                    t.traceId}
                                </span>
                                {/* Compact error count — colored text, no pill. */}
                                {t.errorCount > 0 && (
                                  <span
                                    title={`${t.errorCount} ${t.errorCount === 1 ? "error" : "errors"}`}
                                    className="flex shrink-0 items-center gap-0.75 font-sans text-sm text-red-600 dark:text-red-400"
                                  >
                                    <IconAlertTriangle className="size-3.5 fill-current/20" />
                                    {t.errorCount}
                                  </span>
                                )}
                                {t.errorCount === 0 && t.abortedCount > 0 && (
                                  <span
                                    title="Aborted"
                                    className="flex shrink-0 items-center gap-0.75 font-sans text-sm text-amber-600 dark:text-amber-400"
                                  >
                                    <IconPlayerStopFilled className="size-3.5" />
                                  </span>
                                )}
                              </div>
                              <div className="mt-0.5 flex items-center gap-3 text-xs text-muted-foreground">
                                {t.models.length > 0 && (
                                  <button
                                    type="button"
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      patchParams({ model: t.models[0]! });
                                    }}
                                    title={
                                      t.models.length > 1
                                        ? `${t.models.map(formatModelName).join(", ")} — filter by ${formatModelName(t.models[0])}`
                                        : "Filter by model"
                                    }
                                    className="inline-flex min-w-0 shrink cursor-pointer items-center gap-1 transition-colors hover:text-foreground"
                                  >
                                    <ModelLogo
                                      modelId={t.models[0]}
                                      className="size-2.75 shrink-0"
                                    />
                                    <span className="truncate">
                                      {formatModelName(t.models[0])}
                                      {t.models.length > 1
                                        ? ` +${t.models.length - 1}`
                                        : ""}
                                    </span>
                                  </button>
                                )}
                                {t.sessionId && (
                                  <Link
                                    href={`/sessions/${encodeURIComponent(
                                      t.sessionId
                                    )}`}
                                    onClick={(e) => e.stopPropagation()}
                                    title="View session"
                                    className="inline-flex shrink-0 items-center gap-1 transition-colors hover:text-foreground cursor-pointer"
                                  >
                                    <IconMessage2Filled className="size-3 text-sky-500" />
                                    Session
                                  </Link>
                                )}
                                {t.agentName && (
                                  <Link
                                    href={`/agents/${encodeURIComponent(
                                      t.agentName
                                    )}`}
                                    onClick={(e) => e.stopPropagation()}
                                    title="View agent"
                                    className="inline-flex min-w-0 shrink items-center gap-1 transition-colors hover:text-foreground"
                                  >
                                    <AgentIcon
                                      name={t.agentName}
                                      filled
                                      className="size-3 shrink-0"
                                    />
                                    <span className="truncate">
                                      {t.agentName}
                                    </span>
                                  </Link>
                                )}
                                {t.workflowName && (
                                  <Link
                                    href={`/workflows/${encodeURIComponent(
                                      t.workflowName
                                    )}`}
                                    onClick={(e) => e.stopPropagation()}
                                    title="View workflow"
                                    className="inline-flex min-w-0 shrink items-center gap-1 transition-colors hover:text-foreground"
                                  >
                                    <IconSitemapFilled className="size-3 shrink-0 text-emerald-500" />
                                    <span className="truncate">
                                      {t.workflowName}
                                    </span>
                                  </Link>
                                )}
                                {t.customerId && (
                                  <button
                                    type="button"
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      patchParams({
                                        customer: t.customerId!,
                                      });
                                    }}
                                    title="Filter by customer"
                                    className="inline-flex min-w-0 shrink cursor-pointer items-center gap-1 transition-colors hover:text-foreground"
                                  >
                                    <CustomerAvatar
                                      customerId={t.customerId}
                                      customerName={t.customerName}
                                      imageUrl={t.customerImageUrl}
                                      filled
                                      className="size-3 shrink-0"
                                    />
                                    <span className="truncate">
                                      {t.customerName ?? t.customerId}
                                    </span>
                                  </button>
                                )}
                              </div>
                            </div>
                          </div>
                        </TableCell>
                        {metaKeyFilter && (
                          <TableCell>
                            {t.metadataValue ? (
                              <button
                                type="button"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  patchParams({
                                    metaValue: t.metadataValue!,
                                  });
                                }}
                                title={`Filter by ${metaKeyFilter}: ${t.metadataValue}`}
                                className="block max-w-36 cursor-pointer truncate text-muted-foreground transition-colors hover:text-foreground"
                              >
                                {t.metadataValue}
                              </button>
                            ) : (
                              <span className="text-muted-foreground/40">
                                —
                              </span>
                            )}
                          </TableCell>
                        )}
                        <TableCell className="text-right tabular-nums text-muted-foreground">
                          {formatCount(t.spanCount)}
                        </TableCell>
                        <TableCell className="text-right tabular-nums">
                          {formatTokens(t.totalTokens)}
                        </TableCell>
                        <HeatCell
                          value={t.durationMs}
                          thresholds={durationQuantiles}
                          metric="duration"
                        >
                          {formatSpanDuration(t.durationMs)}
                        </HeatCell>
                        <HeatCell
                          value={t.totalCost}
                          thresholds={costQuantiles}
                          metric="cost"
                          bold
                        >
                          {formatCostFixed(t.totalCost, 6)}
                        </HeatCell>
                        <TableCell className="text-right text-muted-foreground">
                          <RelativeTime value={t.startTime} />
                        </TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </TooltipProvider>

            {!traces.isLoading && rows.length > 0 && (
              <PaginationFooter
                page={page}
                pageSize={pageSize}
                total={summary?.traceCount ?? 0}
                shown={rows.length}
                noun={["trace", "traces"]}
                isFetching={traces.isFetching}
                onPageChange={setPage}
                onPageSizeChange={(s) => patchParams({ size: String(s) })}
                pageSizes={PAGE_SIZES}
              />
            )}
          </div>
        )}
      </div>
    </>
  );
}

// Skeleton column spec for the loading body rows (see TableRowsSkeleton).
const SKELETON_COLS = [
  { w: "w-40", sub: "w-56" },
  { align: "right", w: "w-10" },
  { align: "right", w: "w-12" },
  { align: "right", w: "w-14" },
  { align: "right", w: "w-16" },
  { align: "right", w: "w-14" },
] as const;

/** Original design by Gustavo Fior (@gustavo-fior), co-founder Abdul Haidar and Foglamp Labs.
 * Adapted from foglamp-labs/foglamp apps/web/src/app/(app)/workflows/[name]/workflow-detail-client.tsx under Apache-2.0. */
"use client";

import { Badge } from "../../ui/badge";
import { Button } from "../../ui/button";
import { Skeleton } from "../../ui/skeleton";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "../../ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "../../ui/table";
import {
  IconAlertTriangle,
  IconAlertTriangleFilled,
  IconArrowUpRight,
  IconBoltFilled,
  IconChartAreaFilled,
  IconClockFilled,
  IconCoinFilled,
  IconSitemapFilled,
  IconAffiliateFilled,
} from "@tabler/icons-react";
import { FoglampLink as Link } from "../../lib/link-context";
import { Fragment, useEffect, useMemo, useRef, useState } from "react";

import { AgentIcon } from "../../widgets/leaf/agent-icon";
import { DRAWER_BUTTON_CLASS } from "../../ui/button-styles";
import {
  PaginationFooter,
  SortableHead,
  useTableSort,
} from "../../widgets/data-table";
import { HeatCell } from "../../widgets/heat-cell";
import {
  useDelayedLoading,
  useEntranceOnce,
  useSkeletonShown,
} from "../../hooks/use-app-hooks";
import { navItem } from "../../widgets/nav";
import {
  type FlowNode,
  NodeFlow,
  NodeFlowSkeleton,
} from "../../widgets/leaf/node-flow";
import {
  EmptyState,
  NoProject,
  PageHeader,
  StatCard,
  TableRowsSkeleton,
} from "../../widgets/page-parts";
import { useProject } from "../../widgets/project-context";
import { useRange } from "../../widgets/range-context";
import { RangeControl } from "../../widgets/range-picker";
import { RelativeTime } from "../../widgets/leaf/relative-time";
import {
  Conversation,
  ConversationSkeleton,
  DrawerColumns,
  CustomerValue,
  DrawerRow,
  ExpandChevron,
  FOCUSED_ROW_CLASS,
  Meta,
  MetaEmpty,
  ModelsValue,
  OPEN_ROW_CLASS,
  SessionButton,
  emptyOutputHint,
} from "../../widgets/run-exchange";
import {
  ChartLegend,
  fillBuckets,
  formatBucketFull,
  makeBucketLabel,
  makeEdgeTick,
  themed,
  thinTicks,
  useFrozen,
  useZoomRange,
} from "../../widgets/trend-charts";
import * as AreaChart from "../../charts/evilcharts/charts/area-chart";
import type { ChartConfig } from "../../charts/evilcharts/ui/chart";
import {
  formatCost,
  formatCostFixed,
  formatCount,
  formatDateTime,
  formatDuration,
  formatSpanDuration,
  formatPercent,
  formatTokens,
  parseDateTime,
} from "../../lib/format";
import { customRange } from "../../lib/range";
import { cn } from "../../lib/utils";


type Percentiles = { p50: number; p95: number; p99: number };
export type WorkflowRunRow = { workflowRunId: string; userMessage: string | null; agentNames: string[]; startTime: string; endTime: string; durationMs: number; totalCost: number | null; totalTokens: number; traceCount: number; errorCount: number; firstTraceId: string | null; lastTraceId: string | null };
export type WorkflowTrace = { traceId: string; traceName: string | null; agentName: string | null; startTime: string; durationMs: number; errorCount: number; abortedCount: number; customerId: string | null; customerName: string | null; customerImageUrl: string | null; sessionId: string | null; models: string[] };
export type WorkflowSpan = { parentSpanId: string | null; spanType: string; input: string | null; output: string | null };
export type WorkflowDetailData = {
 summary: { totalCost: number | null; totalTokens: number; errorRate: number | null; erroredRunCount: number; durationMs: Percentiles; runCount: number; traceCount: number; costQuantiles: number[]; durationQuantiles: number[] } | null;
 series: { bucket: string; runCount: number; erroredRunCount: number; durationMs: Percentiles }[];
 runs: WorkflowRunRow[]; pinnedRun?: WorkflowRunRow | null;
 runDetails: Record<string, { traces: WorkflowTrace[] }>;
 traceDetails: Record<string, { spans: WorkflowSpan[] }>;
};
const DEFAULT_DATA: WorkflowDetailData = { summary: { totalCost: 0.0042, totalTokens: 842, errorRate: 0, erroredRunCount: 0, durationMs: { p50: 1200, p95: 1800, p99: 2000 }, runCount: 1, traceCount: 1, costQuantiles: [], durationQuantiles: [] }, series: [], runs: [{ workflowRunId: "run_demo", userMessage: "How can I track my order?", agentNames: ["Support agent"], startTime: "2026-01-01T12:00:00Z", endTime: "2026-01-01T12:00:02Z", durationMs: 1800, totalCost: 0.0042, totalTokens: 842, traceCount: 1, errorCount: 0, firstTraceId: "trace_demo", lastTraceId: "trace_demo" }], runDetails: { run_demo: { traces: [{ traceId: "trace_demo", traceName: "Support request", agentName: "Support agent", startTime: "2026-01-01T12:00:00Z", durationMs: 1800, errorCount: 0, abortedCount: 0, customerId: null, customerName: null, customerImageUrl: null, sessionId: null, models: ["gpt-4o"] }] } }, traceDetails: { trace_demo: { spans: [{ parentSpanId: null, spanType: "agent", input: "How can I track my order?", output: "Please share your order number." }] } } };
type RunRow = WorkflowRunRow;

const UNGROUPED = "__ungrouped__";

const PAGE_SIZES = [25, 50, 100];

// Skeleton column spec for the loading body rows (see TableRowsSkeleton).
const SKELETON_COLS = [
  { icon: true, w: "w-64" },
  { align: "right", w: "w-8" },
  { align: "right", w: "w-12" },
  { align: "right", w: "w-14" },
  { align: "right", w: "w-16" },
] as const;

type RunSortKey = "when" | "duration" | "traces" | "errors" | "cost";

const volumeConfig = {
  runs: { label: "Runs", colors: themed("var(--chart-2)") },
  errors: { label: "Errored", colors: themed("var(--destructive)") },
} satisfies ChartConfig;

const latencyConfig = {
  // neutral-800 on light, neutral-200 on dark — matches the Overview latency chart
  p50: { label: "p50", colors: { light: ["#262626"], dark: ["#e5e5e5"] } },
  p95: { label: "p95", colors: themed("#0090FD") },
  p99: { label: "p99", colors: themed("#FF5513") },
} satisfies ChartConfig;

export function WorkflowDetailBlock({ nameParam = "Support", data = DEFAULT_DATA, isLoading = false, isUpdating = false, initialRun, onNavigate, onRunChange }: { nameParam?: string; data?: WorkflowDetailData; isLoading?: boolean; isUpdating?: boolean; initialRun?: string | null; onNavigate?: (href: string) => void; onRunChange?: (id: string | null) => void }) {
  const entrance = useEntranceOnce();
  const { projectId } = useProject();

  // Shared time window drives the stats, trend charts, and runs table.
  const { range, setRange } = useRange();
  const zoom = useZoomRange();
  // A `?run=` deep link focuses one run: its row opens and is tinted.
  const focusRun = initialRun ?? null;
  // Which run row is expanded (agent flow + exchange drawer). Mirrors `?run=`
  // so an open drawer is deep-linkable.
  const [expanded, setExpanded] = useState<string | null>(focusRun);
  // The row the page was *opened on* (deep link) gets the focused tint and a
  // scroll-into-view; rows the user expands themselves are plain card, like
  // the evals table. Cleared on the first toggle so the tint doesn't follow
  // the `?run=` mirror around.
  const [deepLinked, setDeepLinked] = useState<string | null>(focusRun);
  const focusRef = useRef<HTMLTableRowElement>(null);
  // The deep-linked run, fetched on its own (no window, no paging) so the link
  // always lands on it: it pins above the table whenever the window or the
  // current page doesn't hold it. Captured once so it stays put while the
  // drawer's `?run=` mirror moves to other rows.
  const [pinnedId, setPinnedId] = useState(focusRun);
  useEffect(() => {
    if (initialRun !== undefined) return;
    const id = new URLSearchParams(window.location.search).get("run");
    setExpanded(id);
    setDeepLinked(id);
    setPinnedId(id);
  }, [initialRun]);

  const pinnedRow = data.pinnedRun ?? data.runs.find((run) => run.workflowRunId === pinnedId) ?? null;
  const pinned = { isLoading };
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(PAGE_SIZES[0]);
  // Selected series for each trend chart, driven by the header legends.
  const [volumeSelected, setVolumeSelected] = useState<string | null>(null);
  const [latencySelected, setLatencySelected] = useState<string | null>(null);
  const { sort, toggle } = useTableSort<RunSortKey>();

  const ungrouped = nameParam === UNGROUPED;
  const workflowName = ungrouped ? "" : nameParam;
  const label = ungrouped ? "Ungrouped" : nameParam;

  // Stats + charts always reflect *all* runs in the window (no errors-only), so
  // the error-rate stat stays meaningful when the table is filtered down.
  const summary = { data: data.summary, isLoading };
  const series = { data: data.series, isLoading, isPlaceholderData: isUpdating };
  const sortedRuns = [...data.runs];
  if (sort) {
    const value = (row: WorkflowRunRow) => sort.key === "when" ? Date.parse(row.startTime) : sort.key === "duration" ? row.durationMs : sort.key === "traces" ? row.traceCount : sort.key === "errors" ? row.errorCount : row.totalCost ?? 0;
    sortedRuns.sort((a, b) => (value(a) - value(b)) * (sort.dir === "asc" ? 1 : -1));
  }
  const runs = { data: sortedRuns.slice(page * pageSize, (page + 1) * pageSize), isLoading, isFetching: isUpdating };

  // Widen the window to the pinned run, once, so the stats and charts agree
  // with the row the link asked for instead of reporting an empty range. The
  // filter reset below must not close the deep-linked drawer when this fires.
  const widened = useRef(false);
  const skipReset = useRef(false);
  useEffect(() => {
    if (!pinnedRow || widened.current) return;
    widened.current = true;
    const start = parseDateTime(pinnedRow.startTime);
    const end = parseDateTime(pinnedRow.endTime);
    if (start >= range.from && end <= range.to) return;
    skipReset.current = true;
    setRange(
      customRange(
        new Date(Math.min(start.getTime(), range.from.getTime())),
        new Date(Math.max(end.getTime(), range.to.getTime())),
      ),
    );
  }, [pinnedRow, range, setRange]);

  // Reset paging + any open drawer when the query that defines the result set
  // changes (skipping mount, so a deep-linked drawer survives the first render).
  const mounted = useRef(false);
  // biome-ignore lint/correctness/useExhaustiveDependencies: reset on filter changes only
  useEffect(() => {
    if (!mounted.current) {
      mounted.current = true;
      return;
    }
    if (skipReset.current) {
      skipReset.current = false;
      return;
    }
    setPage(0);
    setExpanded(null);
  }, [range, projectId, sort]);

  const runRows = runs.data ?? [];
  // The pinned run renders above the page only while the page itself doesn't
  // hold it — once the widened window (or a page flip) brings it into the
  // list, it takes its natural place.
  const showPinned =
    !!pinnedRow &&
    !runRows.some((r) => r.workflowRunId === pinnedRow.workflowRunId);

  // Toggle a row's drawer and mirror it in the URL (`?run=`), so the open run
  // can be shared and survives a reload.
  const toggleRun = (id: string) => {
    const next = expanded === id ? null : id;
    setExpanded(next);
    setDeepLinked(null);
    if (onRunChange) onRunChange(next);
    else {
      const url = new URL(window.location.href);
      if (next) url.searchParams.set("run", next);
      else url.searchParams.delete("run");
      window.history.replaceState(window.history.state, "", url);
    }
  };
  // Once the deep-linked run is on the loaded page, scroll it into view.
  // biome-ignore lint/correctness/useExhaustiveDependencies: re-run as runs load
  useEffect(() => {
    if (deepLinked && focusRef.current) {
      focusRef.current.scrollIntoView({ block: "center", behavior: "smooth" });
    }
  }, [deepLinked, runs.data]);
  // Delay the skeleton so fast loads don't flash it (see useDelayedLoading).
  const showRunsSkeleton = useDelayedLoading(runs.isLoading);
  // Latch for the entrance fade: the runs table only fades in if this slot
  // never painted a skeleton first (see useSkeletonShown).
  const runsSkeletonShown = useSkeletonShown(showRunsSkeleton);

  // While a range change refetches, the trend charts hold the previous view —
  // the rows *and* the window they were fetched for, so fill, ticks, and label
  // format stay mutually consistent — dimmed (isUpdating), then swap to the
  // fresh view in one transition.
  const chartsStale = series.isPlaceholderData;
  const chartView = useFrozen(
    { series: series.data, from: range.from, to: range.to },
    chartsStale,
  );
  const chartWindowMs = chartView.to.getTime() - chartView.from.getTime();
  const bucketLabel = useMemo(
    () => makeBucketLabel(chartWindowMs),
    [chartWindowMs],
  );
  const edgeTick = useMemo(() => makeEdgeTick(bucketLabel), [bucketLabel]);
  // Keep the raw bucket as the x value (formatted on the axis) so we can thin
  // the ticks and edge-anchor the first/last labels. Zero-filled so quiet
  // stretches keep their width on the x-axis.
  const seriesData = useMemo(
    () =>
      fillBuckets(
        (chartView.series ?? []).map((r) => ({
          bucket: r.bucket,
          runs: r.runCount,
          errors: r.erroredRunCount,
          p50: r.durationMs.p50,
          p95: r.durationMs.p95,
          p99: r.durationMs.p99,
        })),
        chartView.from,
        chartView.to,
        (bucket) => ({ bucket, runs: 0, errors: 0, p50: 0, p95: 0, p99: 0 }),
      ),
    [chartView],
  );
  // Latency as a stacked *band* chart: each area plots the delta to the band
  // below it (p50, p95−p50, p99−p95), so its gradient fill is bounded between
  // two percentile lines instead of bleeding down to the axis. The stack tops
  // land exactly on p50/p95/p99; the absolutes ride along for the tooltip.
  const latencyData = useMemo(
    () =>
      seriesData.map((r) => ({
        bucket: r.bucket,
        p50: r.p50,
        p95: Math.max(0, r.p95 - r.p50),
        p99: Math.max(0, r.p99 - r.p95),
        p50Abs: r.p50,
        p95Abs: r.p95,
        p99Abs: r.p99,
      })),
    [seriesData],
  );
  const seriesTicks = useMemo(
    () =>
      thinTicks(
        seriesData.map((d) => d.bucket),
        bucketLabel,
      ),
    [seriesData, bucketLabel],
  );

  const back = navItem("/workflows");

  if (!projectId) {
    return (
      <>
        <PageHeader title={label} back={back} />
        <NoProject />
      </>
    );
  }

  const stats = summary.data;
  // Global 20/40/60/80th-percentile thresholds for the heat-tinted cells,
  // computed server-side over the whole filtered window (not just this page).
  const costQuantiles = stats?.costQuantiles ?? [];
  const durationQuantiles = stats?.durationQuantiles ?? [];
  const totalRuns = stats?.runCount ?? 0;
  // No runs at all in this window (not just filtered away). Wait for the
  // summary so a slow rollup doesn't flash the empty state before stats land.
  // A pinned deep-link run counts as a run, even before the window widens to
  // include it.
  const noRuns =
    !runs.isLoading &&
    !summary.isLoading &&
    (stats?.runCount ?? 0) === 0 &&
    !pinnedRow &&
    !(pinnedId && pinned.isLoading);
  const seriesLoading = series.isLoading;

  // One run row plus, when open, its drawer — shared by the paged rows and
  // the pinned deep-link run.
  const renderRun = (r: RunRow) => {
    const isOpen = expanded === r.workflowRunId;
    const isFocused = r.workflowRunId === deepLinked;
    return (
      <Fragment key={r.workflowRunId}>
        <TableRow
          ref={isFocused ? focusRef : undefined}
          interactive
          aria-expanded={isOpen}
          onClick={() => toggleRun(r.workflowRunId)}
          className={cn(
            "group",
            isOpen && OPEN_ROW_CLASS,
            isFocused && FOCUSED_ROW_CLASS,
          )}
        >
          {/* Content-first: the run's opening user message
              (from its first trace), falling back to the
              id; the agents involved trail on the right. */}
          <TableCell className="h-12 font-normal">
            <div className="flex items-center gap-2">
              <ExpandChevron open={isOpen} />
              <span className="truncate">
                {r.userMessage ?? (
                  <span className="font-mono text-xs text-muted-foreground">
                    {r.workflowRunId}
                  </span>
                )}
              </span>
              {/* Compact error count — colored text, no pill. */}
              {r.errorCount > 0 && (
                <span
                  title={`${r.errorCount} ${r.errorCount === 1 ? "error" : "errors"}`}
                  className="flex shrink-0 items-center gap-0.75 font-sans text-sm text-red-600 dark:text-red-400"
                >
                  <IconAlertTriangle className="size-3.5 fill-current/20" />
                  {r.errorCount}
                </span>
              )}
              <AgentStack names={r.agentNames} />
            </div>
          </TableCell>
          <TableCell className="text-right tabular-nums">
            {formatCount(r.traceCount)}
          </TableCell>
          <HeatCell
            value={r.durationMs}
            thresholds={durationQuantiles}
            metric="duration"
          >
            {formatSpanDuration(r.durationMs)}
          </HeatCell>
          <HeatCell
            value={r.totalCost}
            thresholds={costQuantiles}
            metric="cost"
            bold
          >
            {formatCost(r.totalCost)}
          </HeatCell>
          <TableCell className="text-right text-muted-foreground">
            <RelativeTime value={r.startTime} />
          </TableCell>
        </TableRow>
        {isOpen && (
          <RunDrawer
            run={r}
            data={data}
            onNavigate={onNavigate}
            colSpan={5}
          />
        )}
      </Fragment>
    );
  };

  return (
    <>
      <div className={cn(entrance && "page-fade-in")}>
        <PageHeader
          title={label}
          back={back}
          actions={<RangeControl value={range} onChange={setRange} />}
        />
      </div>

      {noRuns ? (
        <div className={cn(entrance && "page-fade-in", "px-8")}>
          <EmptyState
            icon={IconSitemapFilled}
            title="No runs in this range"
            description="Try widening the time range, or this workflow has no runs yet."
          />
        </div>
      ) : (
        <>
          {/* Stat strip — totals over all runs in the window. */}
          <section
            className={cn(
              "grid grid-cols-2 gap-4 md:grid-cols-4 px-8 mt-1",
              entrance && "page-fade-in",
            )}
          >
            <StatCard
              icon={IconCoinFilled}
              iconClassName="text-amber-400 dark:text-yellow-500"
              size="sm"
              label="Total cost"
              value={stats?.totalCost ?? "—"}
              formatValue={(n) => formatCostFixed(n, 4)}
              hint={`${formatTokens(stats?.totalTokens ?? 0)} tokens`}
            />

            <StatCard
              icon={IconAlertTriangleFilled}
              iconClassName="text-red-500/90 dark:text-red-600/95 mt-px"
              size="sm"
              label="Error rate"
              value={stats?.errorRate ?? "—"}
              formatValue={formatPercent}
              hint={`${formatCount(stats?.erroredRunCount ?? 0)} errored`}
            />
            <StatCard
              icon={IconClockFilled}
              iconClassName="text-sky-400 dark:text-sky-500"
              size="sm"
              label="p95 duration"
              value={stats?.durationMs.p95 ?? 0}
              formatValue={formatDuration}
              hint={`p50 ${formatDuration(stats?.durationMs.p50 ?? 0)}`}
            />
            <StatCard
              icon={IconBoltFilled}
              iconClassName="text-orange-500 dark:text-orange-500"
              size="sm"
              label="Runs"
              value={stats?.runCount ?? 0}
              formatValue={formatCount}
              hint={`${formatCount(stats?.traceCount ?? 0)} traces`}
            />
          </section>

          {/* Trend: run volume + run-duration percentiles over the window. */}
          <section className="grid gap-4 lg:grid-cols-2 px-8">
            <Card size="sm" className={cn(entrance && "page-fade-in")}>
              <CardHeader className="flex flex-row items-center justify-between gap-4">
                <CardTitle>Runs & errors</CardTitle>
                <ChartLegend
                  config={volumeConfig}
                  selected={volumeSelected}
                  onSelect={setVolumeSelected}
                />
              </CardHeader>
              <CardContent className="mt-2">
                {!seriesLoading && seriesData.length === 0 ? (
                  <EmptyState
                    icon={IconChartAreaFilled}
                    title="No data in this range"
                  />
                ) : (
                  <AreaChart.EvilAreaChart
                    config={volumeConfig}
                    data={seriesData}
                    isLoading={seriesLoading}
                    isUpdating={chartsStale}
                    xDataKey="bucket"
                    syncId="workflow-trends"
                    onZoomSelect={zoom.zoomTo}
                    onZoomReset={zoom.reset}
                    selectedDataKey={volumeSelected}
                    onSelectionChange={setVolumeSelected}
                    className="h-55 w-full"
                    chartProps={{
                      // left: 2 (vs Recharts' default 5) tucks the auto-width
                      // y-axis labels closer to the card content edge.
                      margin: { top: 5, right: 5, bottom: 5, left: 2 },
                    }}
                  >
                    <AreaChart.Grid />
                    <AreaChart.XAxis
                      dataKey="bucket"
                      ticks={seriesTicks}
                      tickFormatter={bucketLabel}
                      interval={0}
                      tick={edgeTick}
                    />
                    <AreaChart.YAxis
                      allowDecimals={false}
                      tickFormatter={(v) => formatCount(Number(v))}
                    />
                    <AreaChart.Tooltip
                      labelFormatter={(v) => formatBucketFull(String(v))}
                    />
                    <AreaChart.Area dataKey="runs" strokeVariant="solid" />
                    <AreaChart.Area
                      dataKey="errors"
                      strokeVariant="solid"
                      variant="lines"
                    />
                  </AreaChart.EvilAreaChart>
                )}
              </CardContent>
            </Card>

            <Card size="sm" className={cn(entrance && "page-fade-in")}>
              <CardHeader className="flex flex-row items-center justify-between gap-4">
                <CardTitle>Run duration</CardTitle>
                <ChartLegend
                  config={latencyConfig}
                  selected={latencySelected}
                  onSelect={setLatencySelected}
                />
              </CardHeader>
              <CardContent className="mt-2">
                {!seriesLoading && seriesData.length === 0 ? (
                  <EmptyState
                    icon={IconChartAreaFilled}
                    title="No data in this range"
                  />
                ) : (
                  <AreaChart.EvilAreaChart
                    config={latencyConfig}
                    data={latencyData}
                    isLoading={seriesLoading}
                    isUpdating={chartsStale}
                    xDataKey="bucket"
                    syncId="workflow-trends"
                    onZoomSelect={zoom.zoomTo}
                    onZoomReset={zoom.reset}
                    stackType="stacked"
                    selectedDataKey={latencySelected}
                    onSelectionChange={setLatencySelected}
                    className="h-55 w-full"
                    chartProps={{
                      // left: 2 (vs Recharts' default 5) tucks the auto-width
                      // y-axis labels closer to the card content edge.
                      margin: { top: 5, right: 5, bottom: 5, left: 2 },
                    }}
                  >
                    <AreaChart.Grid />
                    <AreaChart.XAxis
                      dataKey="bucket"
                      ticks={seriesTicks}
                      tickFormatter={bucketLabel}
                      interval={0}
                      tick={edgeTick}
                    />
                    <AreaChart.YAxis
                      tickFormatter={(v) => formatDuration(Number(v))}
                    />
                    <AreaChart.Tooltip
                      labelFormatter={(v) => formatBucketFull(String(v))}
                      valueFormatter={(_v, key, row) =>
                        formatDuration(Number(row[`${key}Abs`] ?? _v))
                      }
                      reverse
                    />
                    {/* Stacked deltas (see latencyData): draw bottom band → top
                        so the stack reads p50, then p95−p50, then p99−p95. */}
                    <AreaChart.Area dataKey="p50" strokeVariant="solid" />
                    <AreaChart.Area dataKey="p95" strokeVariant="solid" />
                    <AreaChart.Area dataKey="p99" strokeVariant="solid" />
                  </AreaChart.EvilAreaChart>
                )}
              </CardContent>
            </Card>
          </section>

          {/* Runs table — click a row to open its agent flow + exchange. */}
          <div className="flex flex-col gap-3 mt-4">
            {!runs.isLoading && runRows.length === 0 && !showPinned ? (
              <div
                className={cn(
                  entrance && !runsSkeletonShown && "page-fade-in",
                  "px-8",
                )}
              >
                <EmptyState
                  icon={IconSitemapFilled}
                  title="No runs in this range"
                  description="Try widening the time range."
                />
              </div>
            ) : (
              // Table mounted while loading (skeleton rows in the body) so the
              // swap to data doesn't reflow; footer flush with the last row.
              <div
                className={cn(
                  "flex flex-col",
                  entrance && !runsSkeletonShown && "page-fade-in",
                )}
              >
                {/* pr-11 (not the default pr-9): the range picker lives in the
                    page header here (px-8) rather than a toolbar (pr-6), so
                    the last column needs 8px more to line up with its chevron
                    the way the list pages do. */}
                <Table
                  className="table-fixed [&_th:last-child]:pr-11 [&_td:last-child]:pr-11"
                  stickyHeader
                >
                  <TableHeader>
                    <TableRow>
                      <TableHead>Run</TableHead>
                      <SortableHead
                        sortKey="traces"
                        sort={sort}
                        onSort={toggle}
                        align="right"
                        className="w-24"
                      >
                        Traces
                      </SortableHead>
                      <SortableHead
                        sortKey="duration"
                        sort={sort}
                        onSort={toggle}
                        align="right"
                        className="w-28"
                      >
                        Duration
                      </SortableHead>
                      <SortableHead
                        sortKey="cost"
                        sort={sort}
                        onSort={toggle}
                        align="right"
                        className="w-28"
                      >
                        Cost
                      </SortableHead>
                      <SortableHead
                        sortKey="when"
                        sort={sort}
                        onSort={toggle}
                        align="right"
                        className="w-32"
                      >
                        When
                      </SortableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {runs.isLoading ? (
                      showRunsSkeleton ? (
                        <TableRowsSkeleton cols={SKELETON_COLS} />
                      ) : null
                    ) : (
<>
                        {showPinned && pinnedRow && renderRun(pinnedRow)}
                        {runRows.map(renderRun)}
                      </>
                    )}
                  </TableBody>
                </Table>

                {!runs.isLoading && (
                  <PaginationFooter
                    page={page}
                    pageSize={pageSize}
                    total={totalRuns}
                    shown={runRows.length}
                    noun={["run", "runs"]}
                    isFetching={runs.isFetching}
                    onPageChange={setPage}
                    onPageSizeChange={(size) => {
                      setPageSize(size);
                      setPage(0);
                    }}
                    pageSizes={PAGE_SIZES}
                  />
                )}
              </div>
            )}
          </div>
        </>
      )}
    </>
  );
}

/** The agents a run touched, in first-run order: a tight stack of their
 * tinted ghosts (up to four, then "+n"), each named on hover. Sits at the end
 * of the Run cell so the message text truncates before the agents do. */
function AgentStack({ names }: { names: string[] }) {
  if (names.length === 0) return null;
  const shown = names.slice(0, 4);
  const rest = names.length - shown.length;
  return (
    <span
      className="ml-auto flex shrink-0 items-center gap-1 pl-2"
      title={names.join(" → ")}
    >
      {shown.map((n) => (
        <AgentIcon key={n} name={n} className="size-3.5" />
      ))}
      {rest > 0 && (
        <span className="text-xs text-muted-foreground tabular-nums">
          +{rest}
        </span>
      )}
    </span>
  );
}

/** Expanded row: the run's overview on the left (timing, size, cost), its
 * agent hand-offs as a flow and the whole run's exchange — the first trace's
 * opening message to the last trace's answer — on the right. Lazy-fetches the
 * run's traces and the two traces that bracket it. */
function RunDrawer({
  run,
  data,
  onNavigate,
  colSpan,
}: {
  run: RunRow;
  data: WorkflowDetailData;
  onNavigate?: (href: string) => void;
  colSpan: number;
}) {
  const router = { push: (href: string) => { if (onNavigate) onNavigate(href); else window.location.assign(href); } };
  const detail = { data: data.runDetails[run.workflowRunId], isLoading: false };
  const traces = detail.data?.traces ?? [];
  const firstId = run.firstTraceId ?? traces[0]?.traceId ?? null;
  const lastId = run.lastTraceId ?? traces[traces.length - 1]?.traceId ?? null;
  const first = { data: firstId ? data.traceDetails[firstId] : undefined, isLoading: false };
  const last = { data: lastId ? data.traceDetails[lastId] : undefined, isLoading: false };
  type Span = NonNullable<typeof first.data>["spans"][number];
  const rootOf = (spans: Span[] | undefined) =>
    spans?.find((s) => !s.parentSpanId) ?? spans?.[0];
  const firstRoot = rootOf(first.data?.spans);
  const lastRoot = lastId === firstId ? firstRoot : rootOf(last.data?.spans);
  const exchangeLoading =
    first.isLoading || (lastId !== firstId && last.isLoading);

  // Run-level context from its traces: the first trace's customer/session
  // (a run belongs to one conversation), and every model any trace used, in
  // first-use order.
  const customer = traces.find((t) => t.customerId) ?? null;
  const sessionId = traces.find((t) => t.sessionId)?.sessionId ?? null;
  const models = [...new Set(traces.flatMap((t) => t.models))];

  const nodes: FlowNode[] = traces.map((t) => ({
    id: t.traceId,
    icon: <AgentIcon name={t.agentName} className="size-3.25" />,
    label: t.agentName ?? t.traceName ?? "trace",
    sublabel: t.agentName && t.traceName !== t.agentName ? t.traceName : null,
    status: t.errorCount > 0 ? "error" : t.abortedCount > 0 ? "aborted" : "ok",
    timestamp: t.startTime,
    durationMs: t.durationMs,
  }));

  return (
    <DrawerRow colSpan={colSpan} className="pt-6">
      <DrawerColumns
        overview={
          <>
            {run.errorCount > 0 && (
              <div className="flex h-5 items-center">
                <Badge variant="rose" className="font-sans">
                  <IconAlertTriangle />
                  {formatCount(run.errorCount)}
                  {run.errorCount === 1 ? " error" : " errors"}
                </Badge>
              </div>
            )}
            <div className="grid grid-cols-2 gap-4">
              <Meta label="Started" value={formatDateTime(run.startTime)} />
              <Meta
                label="Duration"
                value={formatSpanDuration(run.durationMs)}
              />
              <Meta label="Traces" value={formatCount(run.traceCount)} />
              <Meta label="Tokens" value={formatTokens(run.totalTokens)} />
              <Meta
                label="Cost"
                value={
                  run.totalCost == null ? (
                    <MetaEmpty />
                  ) : (
                    formatCost(run.totalCost, 4)
                  )
                }
              />
              <Meta
                label="Customer"
                value={
                  detail.isLoading ? (
                    <Skeleton className="h-3.5 w-20" />
                  ) : (
                    <CustomerValue
                      customerId={customer?.customerId ?? null}
                      customerName={customer?.customerName}
                      imageUrl={customer?.customerImageUrl}
                    />
                  )
                }
              />

              <Meta
                label={models.length === 1 ? "Model" : "Models"}
                className="col-span-2"
                value={
                  detail.isLoading ? (
                    <Skeleton className="h-3.5 w-24" />
                  ) : (
                    <ModelsValue models={models} />
                  )
                }
              />
            </div>
            <div className="flex flex-wrap gap-2.5 mt-3">
              {firstId && (
                <Button
                  size="sm"
                  variant="secondary"
                  className={cn("w-fit", DRAWER_BUTTON_CLASS)}
                  render={
                    // biome-ignore lint/suspicious/noExplicitAny: typed-routes string href
                    <Link
                      href={`/traces/${encodeURIComponent(firstId)}`}
                    />
                  }
                >
                  <IconAffiliateFilled className="text-[#8b5e34] dark:text-[#c9a888]" />
                  See first trace
                  <IconArrowUpRight className="mt-px" />
                </Button>
              )}
              {sessionId && <SessionButton sessionId={sessionId} />}
            </div>
          </>
        }
      >
        <div className="flex flex-col gap-5">
          <DrawerSection label="Agents">
            {detail.isLoading ? (
              <NodeFlowSkeleton count={Math.min(run.traceCount, 6)} />
            ) : nodes.length === 0 ? (
              <span className="text-xs text-muted-foreground">
                No traces in this run.
              </span>
            ) : (
              <NodeFlow
                nodes={nodes}
                onNodeClick={(id) =>
                  router.push(`/traces/${encodeURIComponent(id)}`)
                }
              />
            )}
          </DrawerSection>
          <DrawerSection label="Exchange">
            {exchangeLoading ? (
              <ConversationSkeleton />
            ) : !firstRoot ? (
              <span className="text-xs text-muted-foreground">
                Trace payload unavailable.
              </span>
            ) : (
              <Conversation
                input={firstRoot.input}
                output={lastRoot?.output ?? null}
                emptyHint={emptyOutputHint(
                  (lastId === firstId ? first.data?.spans : last.data?.spans) ??
                    [],
                )}
                clamp={320}
              />
            )}
          </DrawerSection>
        </div>
      </DrawerColumns>
    </DrawerRow>
  );
}

function DrawerSection({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div className="flex flex-col gap-2">
      <span className="text-xs text-muted-foreground">{label}</span>
      {children}
    </div>
  );
}

