			</mask>
			<pattern
				id={`${id}-lines`}
				patternUnits="userSpaceOnUse"
				width="100%"
				height="100%"
			>
				<rect
					width="100%"
					height="100%"
					fill={`url(#${id}-colors-${dataKey})`}
					mask={`url(#${id}-lines-mask)`}
				/>
			</pattern>
		</>
