/** Resolve the canonical vendor key for a (provider, modelId) pair, or null. */
export function resolveVendorKey(
	provider?: string | null,
	modelId?: string | null,
): string | null {
	const id = modelId?.toLowerCase();
	// Prefer the vendor slug embedded in a "vendor/model" id, then a vendor
	// segment of a dot-namespaced Bedrock id ("us.anthropic.claude-…-v1:0" — the
	// model's own vendor must beat the "bedrock" provider), then the provider.
	const fromSlash = id?.includes("/") ? id.split("/")[0] : undefined;
	const fromDots = id?.includes(".")
		? id
				.split(".")
				.slice(0, -1)
				.find((segment) => LOGOS[segment])
		: undefined;
	const fromProvider = provider?.split(".")[0]?.toLowerCase();
	for (const key of [fromSlash, fromDots, fromProvider]) {
		if (key && LOGOS[key]) return key;
	}
	// Fall back to the model id's own name (e.g. a bare "gemini-3.1-flash-lite"),
	// also trying the last dotted segment so a namespaced id still gets a hint.
	if (id) {
		const tail = id.split(".").at(-1);
		for (const [pattern, vendor] of MODEL_ID_HINTS) {
			if ((pattern.test(id) || (tail && pattern.test(tail))) && LOGOS[vendor])
				return vendor;
		}
	}
	return null;
}

/** Resolve the brand logo for a (provider, modelId) pair, or null if unknown. */
export function resolveModelLogo(
	provider?: string | null,
	modelId?: string | null,
): Logo | null {
	const key = resolveVendorKey(provider, modelId);
	return key ? (LOGOS[key] ?? null) : null;
}

// Tokens that should keep a specific casing rather than being plain-title-cased.
const MODEL_WORD_CASE: Record<string, string> = {
	gpt: "GPT",
	chatgpt: "ChatGPT",
	llm: "LLM",
	ai: "AI",
	oss: "OSS",
	moe: "MoE",
	hd: "HD",
	tts: "TTS",
	vl: "VL",
	deepseek: "DeepSeek",
	openai: "OpenAI",
	xai: "xAI",
	qwq: "QwQ",
	minimax: "MiniMax",
	glm: "GLM",
};

/**
 * Turn a raw model id into a human-friendly display name — a heuristic, not a
 * lookup, so unknown ids still come out reasonably titled. Examples:
 * "gemini-3.1-flash-lite" → "Gemini 3.1 Flash Lite",
 * "anthropic/claude-sonnet-4-6" → "Claude Sonnet 4.6",
 * "gpt-4o-mini" → "GPT-4o Mini", "deepseek-r1" → "DeepSeek R1".
 */
export function formatModelName(modelId?: string | null): string {
	if (!modelId) return "—";
	// Drop the vendor prefix ("anthropic/…").
	let id = modelId.includes("/")
		? modelId.slice(modelId.lastIndexOf("/") + 1)
		: modelId;
	// Bedrock ids ("us.anthropic.claude-haiku-4-5-…-v1:0"): drop the ":0" build
	// counter, keep only the model segment of the dotted namespace (guarded so a
	// version dot like "gpt-4.1" survives), and drop the "-v1" build suffix.
	const wasBedrock = /:\d+$/.test(id);
	id = id.replace(/:\d+$/, "");
	const lastDotSegment = id.split(".").at(-1);
	const isDotNamespaced =
		id.includes(".") && !!lastDotSegment && /^[a-z]/i.test(lastDotSegment);
	if (isDotNamespaced) id = lastDotSegment;
	if (wasBedrock || isDotNamespaced) id = id.replace(/-v\d+$/i, "");
	// Then any trailing date stamp (YYYY-MM-DD / YYYYMMDD / YYMMDD) or "-latest"
	// build pointer.
	id = id
		.replace(/[-@](\d{4}-\d{2}-\d{2}|\d{8}|\d{6})$/i, "")
		.replace(/-latest$/i, "");

	const parts = id.split(/[-_]/).filter(Boolean);
	// Merge runs of ≥2 consecutive pure-digit parts into a dotted version, so a
	// hyphenated "…-4-6" reads as "4.6".
	const tokens: string[] = [];
	for (let i = 0; i < parts.length; i++) {
		if (/^\d+$/.test(parts[i])) {
			const run = [parts[i]];
			while (i + 1 < parts.length && /^\d+$/.test(parts[i + 1]))
				run.push(parts[++i]);
			tokens.push(run.join("."));
		} else {
			tokens.push(parts[i]);
		}
	}

	const words = tokens.map((t) => {
		const cased = MODEL_WORD_CASE[t.toLowerCase()];
		if (cased) return cased;
		// Version / size token (starts with a digit): keep as-is, but uppercase a
		// params suffix like "70b" → "70B" (leave "4o" alone — it's not a size).
		if (/^\d/.test(t)) return t.replace(/(\d)b$/i, "$1B");
		// Word, possibly with a trailing version ("r1", "v3"): capitalize the lead.
		return t.charAt(0).toUpperCase() + t.slice(1);
	});

	// Keep the familiar "GPT-4o" hyphenation when a number follows the acronym.
	const out: string[] = [];
	for (const w of words) {
		if (out.at(-1) === "GPT" && /^\d/.test(w)) out[out.length - 1] = `GPT-${w}`;
		else out.push(w);
	}
	return out.join(" ");
}

/** Resolve a brand accent color for a (provider, modelId) pair, or null. */
export function modelBrandColor(
	provider?: string | null,
	modelId?: string | null,
): string | null {
	const key = resolveVendorKey(provider, modelId);
	return key ? (VENDOR_COLORS[key] ?? null) : null;
}

/**
 * Renders the brand logo for a model/provider, falling back to a neutral chip
 * icon when the vendor isn't recognized.
 */
export function ModelLogo({
	provider,
	modelId,
	className,
}: {
	provider?: string | null;
	modelId?: string | null;
	className?: string;
}) {
	const Logo = resolveModelLogo(provider, modelId);
	if (!Logo) {
		return (
			<IconCpu
				className={cn("size-4 text-muted-foreground", className)}
				aria-hidden
			/>
		);
	}
	return <Logo className={cn("size-4", className)} aria-hidden />;
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/lib/format.ts; derived here under Apache-2.0.
 */
const usdFormatters = new Map<string, Intl.NumberFormat>();
function usdFormatter(minDecimals: number, maxDecimals: number) {
	const key = `${minDecimals}:${maxDecimals}`;
	let f = usdFormatters.get(key);
	if (!f) {
		f = new Intl.NumberFormat("en-US", {
			style: "currency",
			currency: "USD",
			minimumFractionDigits: minDecimals,
			maximumFractionDigits: maxDecimals,
		});
		usdFormatters.set(key, f);
	}
	return f;
}

/** A cost value; `null`/`undefined` → em dash (unpriced, never $0). `maxDecimals`
 * caps the fractional digits — 6 (full precision) by default, 4 for the more
 * compact stat-card treatment. Trailing zeros are trimmed back to 2 decimals. */
export function formatCost(
	value: number | null | undefined,
	maxDecimals = 6,
): string {
	if (value === null || value === undefined) return "—";
	return usdFormatter(2, maxDecimals).format(value);
}

/** A cost value padded to exactly `decimals` fraction digits, so a column of
 * them lines up on the decimal point ("$0.003350" above "$0.002773") instead of
 * raggedly trimming trailing zeros. For table cells; elsewhere use `formatCost`,
 * which keeps numbers short. */
export function formatCostFixed(
	value: number | null | undefined,
	decimals: number,
): string {
	if (value === null || value === undefined) return "—";
	return usdFormatter(decimals, decimals).format(value);
}

const compact = new Intl.NumberFormat("en-US", { notation: "compact" });
const plain = new Intl.NumberFormat("en-US");

// Count formatters round first: counts are integers by definition, but animated
// stat tickers feed them fractional in-between frames, which would otherwise
// render decimals mid-tween ("1,234.567").
export function formatCount(value: number): string {
	const n = Math.round(value);
	return n >= 1000 ? compact.format(n) : plain.format(n);
}

/** A count with no compaction — "1,024", never "1K". For operator figures where
 * the exact number is the point and 1,024 vs 1,499 must not both read "1K". */
export function formatExactCount(value: number): string {
	return plain.format(Math.round(value));
}

export function formatTokens(value: number): string {
	return compact.format(value);
}

/** Milliseconds → human duration (µs/ms/s/m/h/d). */
export function formatDuration(ms: number): string {
	if (!Number.isFinite(ms)) return "—";
	// Exact zero reads as "0s" (not "0µs") everywhere — e.g. latency axes anchored
	// at the origin.
	if (ms === 0) return "0s";
	if (ms < 1) return `${Math.round(ms * 1000)}µs`;
	if (ms < 1000) return `${Math.round(ms)}ms`;
	if (ms < 60_000) return `${(ms / 1000).toFixed(2)}s`;
	// Beyond a minute, build from the largest non-zero unit and show at most two
	// components so e.g. an even hour reads "1h", not "60m 0s".
	const totalSec = Math.round(ms / 1000);
	const d = Math.floor(totalSec / 86_400);
	const h = Math.floor((totalSec % 86_400) / 3600);
	const m = Math.floor((totalSec % 3600) / 60);
	const s = totalSec % 60;
	const parts = [];
	if (d) parts.push(`${d}d`);
	if (h) parts.push(`${h}h`);
	if (m) parts.push(`${m}m`);
	if (s) parts.push(`${s}s`);
	return parts.slice(0, 2).join(" ") || "0s";
}

/** A recorded span/trace duration. Storage is whole milliseconds, so an exact 0
 * means "finished in under 1ms", not "took no time" — render it as such. Axes
 * and aggregates should keep using formatDuration ("0s" at the origin). */
export function formatSpanDuration(ms: number): string {
	if (ms === 0) return "<1ms";
	return formatDuration(ms);
}

export function formatPercent(fraction: number | null | undefined): string {
	if (fraction === null || fraction === undefined) return "—";
	return `${Math.round(fraction * 100)}%`;
}

/** ClickHouse DateTime strings ('YYYY-MM-DD HH:MM:SS', UTC) or ISO → Date. */
export function parseDateTime(value: string | Date): Date {
	if (value instanceof Date) return value;

	const normalized = value.replace(" ", "T");
	const hasTimezone = /(?:Z|[+-]\d{2}:?\d{2})$/i.test(normalized);
	return new Date(hasTimezone ? normalized : `${normalized}Z`);
}

/** ClickHouse DateTime strings ('YYYY-MM-DD HH:MM:SS', UTC) or ISO → local. */
export function formatDateTime(
	value: string | Date | null | undefined,
): string {
	if (!value) return "—";
	const d = parseDateTime(value);
	if (Number.isNaN(d.getTime())) return String(value);
	return d.toLocaleString(undefined, {
		month: "short",
		day: "numeric",
		hour: "2-digit",
		minute: "2-digit",
		second: "2-digit",
		// Always 24-hour, regardless of the viewer's locale default.
		hour12: false,
	});
}

export function formatRelative(
	value: string | Date | null | undefined,
): string {
	if (!value) return "—";
	const d = parseDateTime(value);
	const diff = Date.now() - d.getTime();
	if (Number.isNaN(diff)) return String(value);
	// Clamp clock skew: a server timestamp slightly ahead of the client must not
	// render as "-3s ago".
	const sec = Math.max(0, Math.round(diff / 1000));
	if (sec < 60) return `${sec}s ago`;
	const min = Math.round(sec / 60);
	if (min < 60) return `${min}m ago`;
	const hr = Math.round(min / 60);
	if (hr < 24) return `${hr}h ago`;
	return `${Math.round(hr / 24)}d ago`;
}

export type Delta = { pct: number; dir: "up" | "down" | "flat" };

/**
 * Period-over-period change as a fraction + direction. `null` when there's no
 * baseline to compare against (previous is null/zero) — the caller renders "—".
 */
export function formatDelta(
	current: number | null | undefined,
	previous: number | null | undefined,
): Delta | null {
	if (current === null || current === undefined) return null;
	if (previous === null || previous === undefined || previous === 0)
		return null;
	const pct = (current - previous) / previous;
	const dir = Math.abs(pct) < 0.0001 ? "flat" : pct > 0 ? "up" : "down";
	return { pct, dir };
}

/** Extrapolate a window's cost to a 30-day run-rate. `null` when cost is unknown. */
export function projectMonthlyCost(
	cost: number | null | undefined,
	windowMs: number,
): number | null {
	if (cost === null || cost === undefined || windowMs <= 0) return null;
	const THIRTY_DAYS = 30 * 24 * 60 * 60 * 1000;
	return (cost / windowMs) * THIRTY_DAYS;
}

"use client";

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

import * as React from "react";

type FoglampLinkComponent = React.ElementType;

const FoglampLinkContext = React.createContext<FoglampLinkComponent>("a");

export type FoglampLinkProviderProps = {
	/** Router or link component that should render every FoglampLink below it. */
	component: FoglampLinkComponent;
	children: React.ReactNode;
};

export function FoglampLinkProvider({
	component,
	children,
}: FoglampLinkProviderProps) {
	return (
		<FoglampLinkContext.Provider value={component}>
			{children}
		</FoglampLinkContext.Provider>
	);
}

/**
 * A link with no wrapper of its own. The provider component receives the
 * original props directly, so the rendered DOM and styling stay with the
 * router's link implementation. A per-link component or `as` can override it.
 */
export type FoglampLinkProps<Component extends FoglampLinkComponent = "a"> =
	React.ComponentPropsWithRef<Component> & {
		component?: Component;
		as?: Component;
		/** Common router destination prop, available with the default anchor type. */
		to?: string;
	};

export function FoglampLink<Component extends FoglampLinkComponent = "a">({
	component,
	as,
	...props
}: FoglampLinkProps<Component>) {
	const providerComponent = React.useContext(FoglampLinkContext);
	const LinkComponent = component ?? as ?? providerComponent;

	return React.createElement(LinkComponent, props as React.ComponentPropsWithRef<Component>);
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/app/payload-messages.ts; derived here under Apache-2.0.
 */
export type Part =
	| { kind: "text"; text: string }
	/** Model thinking — same payload as text, but never the answer. */
	| { kind: "reasoning"; text: string }
	| { kind: "tool-call"; name: string; data: unknown }
	| { kind: "tool-result"; name: string; data: unknown }
	| { kind: "tool-error"; name: string; data: unknown }
	/** Binary attachment. The bytes are deliberately dropped — a base64 blob is
	 * never worth rendering, and inlining one wrecks the panel. */
	| { kind: "file"; mediaType: string | null; filename: string | null }
	| { kind: "json"; data: unknown };

export type Message = { role: string | null; parts: Part[] };

function asString(v: unknown): string | null {
	return typeof v === "string" ? v : null;
}

export function partFrom(p: unknown): Part {
	if (typeof p === "string") return { kind: "text", text: p };
	if (p && typeof p === "object") {
		const o = p as Record<string, unknown>;
		if (o.type === "text" && typeof o.text === "string") {
			return { kind: "text", text: o.text };
		}
		if (o.type === "reasoning" && typeof o.text === "string") {
			return { kind: "reasoning", text: o.text };
		}
		if (o.type === "tool-call") {
			return {
				kind: "tool-call",
				name: String(o.toolName ?? o.name ?? "tool"),
				data: o.input ?? o.args ?? {},
			};
		}
		if (o.type === "tool-result") {
			return {
				kind: "tool-result",
				name: String(o.toolName ?? o.name ?? "tool"),
				data: o.output ?? o.result ?? {},
			};
		}
		if (o.type === "tool-error") {
			return {
				kind: "tool-error",
				name: String(o.toolName ?? o.name ?? "tool"),
				data: o.error ?? o.output ?? o.result ?? {},
			};
		}
		if (o.type === "file" || o.type === "image") {
			return {
				kind: "file",
				mediaType: asString(o.mediaType) ?? asString(o.mimeType),
				filename: asString(o.filename) ?? asString(o.name),
			};
		}
	}
	return { kind: "json", data: p };
}

export function partsFrom(content: unknown): Part[] {
	if (typeof content === "string") return [{ kind: "text", text: content }];
	if (Array.isArray(content)) return content.map(partFrom);
	if (content == null) return [];
	return [partFrom(content)];
}

/** Normalize a payload string to a list of messages, or null when it isn't JSON
 * (e.g. a plain markdown answer, or a payload truncated at the 1MB cap — the
 * caller renders the raw string). */
export function toMessages(value: string): Message[] | null {
	let parsed: unknown;
	try {
		parsed = JSON.parse(value);
	} catch {
		return null;
	}
	// A JSON-encoded string is just prose that went through JSON.stringify —
	// unwrap it rather than showing the reader its quotes and escapes.
	if (typeof parsed === "string") {
		return [{ role: null, parts: [{ kind: "text", text: parsed }] }];
	}
	// Any other scalar carries no more structure than the raw string does, and
	// wrapping it in a message block only adds chrome around it.
	if (parsed === null || typeof parsed !== "object") return null;
	const items = Array.isArray(parsed) ? parsed : [parsed];
	if (items.length === 0) return null;
	const hasRoles = items.some(
		(m) => m && typeof m === "object" && "role" in (m as object),
	);
	if (hasRoles) {
		return items.map((m) => {
			const o = (m ?? {}) as Record<string, unknown>;
			return {
				role: typeof o.role === "string" ? o.role : null,
				parts: partsFrom(o.content),
			};
		});
	}
	// An array of plain data objects (no `type` discriminator anywhere — e.g. a
	// tool returning a list of records) is one payload, not a part list:
	// per-item partFrom would render every element as its own JSON block.
	if (
		items.every((i) => i && typeof i === "object" && !("type" in (i as object)))
	) {
		return [{ role: null, parts: [{ kind: "json", data: parsed }] }];
	}
	// A bare array of parts (typical for assistant output) → one roleless block.
	return [{ role: null, parts: items.map(partFrom) }];
}

const ROLE_LINE = /^(user|assistant|system|tool): ?/;
const TOOL_LINE = /^\[tool-(call|result) ([^\]\s]+)\] ?(.*)$/;

/** Reverse the judge's flattening of a message payload: `buildContext`
 * renders `[{role, content}]` as `role: text` blocks separated by blank lines,
 * with tool parts as `[tool-call name] {json}` lines. Parsing that back gives
 * the same turns the transcript renderer shows for the raw trace, while still
 * being exactly the text the judge read. Returns null when no role prefix is
 * found (a plain answer or prose payload). */
export function fromHumanized(value: string): Message[] | null {
	const out: Message[] = [];
	let cur: Message | null = null;
	let text: string[] = [];
	const flush = () => {
		if (!cur) return;
		const t = text.join("\n").trim();
		if (t) cur.parts.push({ kind: "text", text: t });
		text = [];
	};
	for (const rawLine of value.split("\n")) {
		let line = rawLine;
		const role = ROLE_LINE.exec(line);
		if (role) {
			flush();
			cur = { role: role[1] ?? null, parts: [] };
			out.push(cur);
			line = line.slice(role[0].length);
		}
		const tool = TOOL_LINE.exec(line);
		if (tool && cur) {
			flush();
			let data: unknown = tool[3];
			try {
				data = JSON.parse(tool[3] ?? "");
			} catch {}
			cur.parts.push({
				kind: tool[1] === "call" ? "tool-call" : "tool-result",
				name: tool[2] ?? "tool",
				data,
			});
			continue;
		}
		if (cur) text.push(line);
	}
	flush();
	return out.length > 0 ? out : null;
}

/** How many leading messages of `current` are carried over unchanged from
 * `previous` — the fold point for the transcript's "N earlier messages" delta.
 * Non-zero only when `previous` is an exact message-prefix of `current` (agent
 * inputs grow by appending); an edited history or a shrunk list returns 0, so
 * the delta view never hides a message that actually changed. */
export function unchangedPrefix(
	current: Message[],
	previous: Message[],
): number {
	if (previous.length === 0 || current.length <= previous.length) return 0;
	for (let i = 0; i < previous.length; i++) {
		if (JSON.stringify(previous[i]) !== JSON.stringify(current[i])) return 0;
	}
	return previous.length;
}

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

// Line diff (LCS). Used by version inference to align a prompt against the
// canonical prompt of its family, and by the dashboard to show a version's
// template against the previous one. Prompts are small (hundreds of lines), so
// a plain O(n·m) table is fine; oversized inputs fall back to prefix/suffix
// trimming with the middle reported as one replacement.

export type DiffOp = { type: "same" | "add" | "del"; line: string };

const MAX_CELLS = 4_000_000;

export function lineDiff(a: string, b: string): DiffOp[] {
  return diffLines(a.split("\n"), b.split("\n"));
}

export function diffLines(a: string[], b: string[]): DiffOp[] {
  // Trim the common prefix/suffix first — most prompt variants differ in a few
  // lines, so this keeps the table tiny.
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) start++;
  let endA = a.length;
  let endB = b.length;
  while (endA > start && endB > start && a[endA - 1] === b[endB - 1]) {
    endA--;
    endB--;
  }
  const ops: DiffOp[] = [];
  for (let i = 0; i < start; i++) ops.push({ type: "same", line: a[i] as string });

  const midA = a.slice(start, endA);
  const midB = b.slice(start, endB);
  if (midA.length * midB.length > MAX_CELLS) {
    for (const line of midA) ops.push({ type: "del", line });
    for (const line of midB) ops.push({ type: "add", line });
  } else {
    ops.push(...lcsDiff(midA, midB));
  }

  for (let i = endA; i < a.length; i++) ops.push({ type: "same", line: a[i] as string });
  return ops;
}

function lcsDiff(a: string[], b: string[]): DiffOp[] {
  const n = a.length;
  const m = b.length;
  if (n === 0) return b.map((line) => ({ type: "add" as const, line }));
  if (m === 0) return a.map((line) => ({ type: "del" as const, line }));
  // dp[i][j] = LCS length of a[i..] and b[j..]
  const width = m + 1;
  const dp = new Uint32Array((n + 1) * width);
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i * width + j] =
        a[i] === b[j]
          ? (dp[(i + 1) * width + j + 1] as number) + 1
          : Math.max(dp[(i + 1) * width + j] as number, dp[i * width + j + 1] as number);
    }
  }
  const ops: DiffOp[] = [];
  let i = 0;
  let j = 0;
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      ops.push({ type: "same", line: a[i] as string });
      i++;
      j++;
    } else if ((dp[(i + 1) * width + j] as number) >= (dp[i * width + j + 1] as number)) {
      ops.push({ type: "del", line: a[i] as string });
      i++;
    } else {
      ops.push({ type: "add", line: b[j] as string });
      j++;
    }
  }
  while (i < n) ops.push({ type: "del", line: a[i++] as string });
  while (j < m) ops.push({ type: "add", line: b[j++] as string });
  return ops;
}

/**
 * How alike two prompts are, 0..1: shared lines count fully, and replaced
 * lines count by how many words they keep (so a prompt whose only change is a
 * name inside one line still scores high). Symmetric, order-aware.
 */
export function sequenceSimilarity(a: string[], b: string[]): number {
  const longest = Math.max(a.length, b.length);
  if (longest === 0) return 1;
  const ops = diffLines(a, b);
  let credit = 0;
  let k = 0;
  while (k < ops.length) {
    const op = ops[k] as DiffOp;
    if (op.type === "same") {
      credit += 1;
      k++;
      continue;
    }
    const del: string[] = [];
    const add: string[] = [];
    while (k < ops.length && (ops[k] as DiffOp).type !== "same") {
      const h = ops[k] as DiffOp;
      (h.type === "del" ? del : add).push(h.line);
      k++;
    }
    if (del.length > 0 && add.length > 0) {
      credit += wordSimilarity(del.join(" "), add.join(" ")) * ((del.length + add.length) / 2);
    }
  }
  return Math.min(1, credit / longest);
}

const MAX_WORDS = 400;

function wordSimilarity(a: string, b: string): number {
  const wa = a.split(/\s+/).filter(Boolean).slice(0, MAX_WORDS);
  const wb = b.split(/\s+/).filter(Boolean).slice(0, MAX_WORDS);
  const longest = Math.max(wa.length, wb.length);
  if (longest === 0) return 1;
  const same = diffLines(wa, wb).filter((op) => op.type === "same").length;
  return same / longest;
}

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

import { diffLines, sequenceSimilarity } from "./diff";

// Prompt version inference. Input: one row per distinct normalized prompt an
// agent has run with (its hash, text, when it was first/last seen, run count).
// Output: versions — groups of hashes that share a template, ordered by first
// appearance. Nothing here is declared by the user; versions are read off the
// runs.
//
// Two kinds of variation show up between an agent's prompts:
//   • slots — dynamic content the normalizer didn't catch (a user's name, a
//     retrieved snippet). Values interleave in time and differ from each other.
//   • edits — someone changed the prompt. The new text replaces the old one
//     cleanly in time and every later run carries it.
// A prompt joins the current version when it only differs at positions that
// already vary within it, or when it overlaps the version in time. Otherwise it
// is held as a cut candidate until enough runs share the same new text.

export type PromptSample = {
  hash: string;
  /** Normalized prompt text (see normalizePrompt). */
  text: string;
  firstSeen: Date;
  lastSeen: Date;
  runs: number;
};

export type InferredVersion = {
  /** Canonical prompt with varying stretches replaced by a `{…}` line. */
  template: string;
  /** Member hashes, oldest first. */
  hashes: string[];
  /** Number of varying stretches in the template. */
  slotCount: number;
  runs: number;
  firstSeen: Date;
  lastSeen: Date;
};

export type InferOptions = {
  /** Runs a new prompt text needs before it counts as a new version. */
  minRuns?: number;
  /** Overlap tolerated between an old and a new version (rolling deploys). */
  graceMs?: number;
  /** Text similarity below which prompts are unrelated (separate families). */
  similarity?: number;
};

const DEFAULTS: Required<InferOptions> = {
  minRuns: 3,
  graceMs: 5 * 60 * 1000,
  similarity: 0.6,
};

/** The template line standing in for content that varies between runs. */
export const SLOT_LINE = "{…}";

// A member's text expressed in the coordinates of its family's canonical
// prompt: a map from hunk anchor → hunk content. Keys are `rep:<i>` (replaces
// canonical lines starting at i) and `ins:<i>` (inserted before canonical line
// i). A member identical to the canonical has an empty map; "=" below stands
// for "same as canonical" at a position.
type Aligned = Map<string, string>;
const SAME = "=";

type Member = PromptSample & { lines: string[]; aligned: Aligned };

type Family = { canonical: Member; members: Member[] };

export function inferVersions(
  samples: PromptSample[],
  options: InferOptions = {},
): InferredVersion[] {
  const opts = { ...DEFAULTS, ...options };
  const versions: InferredVersion[] = [];
  for (const family of clusterFamilies(samples, opts.similarity)) {
    for (const group of splitFamily(family, opts)) versions.push(render(family, group));
  }
  versions.sort((a, b) => a.firstSeen.getTime() - b.firstSeen.getTime());
  return versions;
}

// --- families ---------------------------------------------------------------

function clusterFamilies(samples: PromptSample[], threshold: number): Family[] {
  // Most-run first so each family's canonical is its most representative text.
  const ordered = [...samples].sort((a, b) => b.runs - a.runs);
  const families: { canonical: PromptSample; lines: string[]; members: PromptSample[] }[] = [];
  for (const s of ordered) {
    const lines = s.text.split("\n");
    let best: (typeof families)[number] | undefined;
    let bestScore = 0;
    for (const f of families) {
      const score = sequenceSimilarity(f.lines, lines);
      if (score > bestScore) {
        bestScore = score;
        best = f;
      }
    }
    if (best && bestScore >= threshold) best.members.push(s);
    else families.push({ canonical: s, lines, members: [s] });
  }
  return families.map((f) => {
    const members = f.members.map((s) => {
      const lines = s.text.split("\n");
      return { ...s, lines, aligned: align(f.lines, lines) };
    });
    const canonical = members.find((m) => m.hash === f.canonical.hash) as Member;
    return { canonical, members };
  });
}

// --- alignment --------------------------------------------------------------

function align(canonical: string[], lines: string[]): Aligned {
  const ops = diffLines(canonical, lines);
  const out: Aligned = new Map();
  let i = 0; // index into canonical
  let k = 0;
  while (k < ops.length) {
    const op = ops[k] as (typeof ops)[number];
    if (op.type === "same") {
      i++;
      k++;
      continue;
    }
    // A hunk: a maximal run of del/add ops. Anchor at the first deleted
    // canonical line, or as an insertion before the next canonical line.
    const anchor = i;
    let deleted = 0;
    const added: string[] = [];
    while (k < ops.length && (ops[k] as (typeof ops)[number]).type !== "same") {
      const h = ops[k] as (typeof ops)[number];
      if (h.type === "del") deleted++;
      else added.push(h.line);
      k++;
    }
    i += deleted;
    const key = deleted > 0 ? `rep:${anchor}` : `ins:${anchor}`;
    out.set(key, `${deleted}\n${added.join("\n")}`);
  }
  return out;
}

function valueAt(m: Member, key: string): string {
  return m.aligned.get(key) ?? SAME;
}

// --- splitting a family into versions ---------------------------------------

class Group {
  members: Member[] = [];
  /** Distinct values seen at each position across the group. */
  values = new Map<string, Set<string>>();
  lastSeen = 0;

  add(m: Member) {
    this.members.push(m);
    this.lastSeen = Math.max(this.lastSeen, m.lastSeen.getTime());
    // Positions this member touches, plus positions the group already tracks
    // (where this member is "=" if it has no entry).
    for (const key of m.aligned.keys()) this.note(key, valueAt(m, key));
    for (const key of this.values.keys()) this.note(key, valueAt(m, key));
  }

  private note(key: string, value: string) {
    let set = this.values.get(key);
    if (!set) {
      set = new Set<string>();
      // Earlier members had no entry here → they were all "=".
      if (this.members.length > 1) set.add(SAME);
      this.values.set(key, set);
    }
    set.add(value);
  }

  /** Positions where the group is unanimous but `m` carries something else. */
  disagreements(m: Member): string[] {
    const out: string[] = [];
    const keys = new Set<string>([...this.values.keys(), ...m.aligned.keys()]);
    for (const key of keys) {
      const set = this.values.get(key);
      const unanimous = set === undefined ? SAME : set.size === 1 ? [...set][0] : undefined;
      if (unanimous === undefined) continue;
      if (valueAt(m, key) !== unanimous) out.push(key);
    }
    return out;
  }
}

function splitFamily(family: Family, opts: Required<InferOptions>): Member[][] {
  const members = [...family.members].sort(
    (a, b) => a.firstSeen.getTime() - b.firstSeen.getTime() || b.runs - a.runs,
  );
  const groups: Member[][] = [];
  let current = new Group();
  // Clean-cut candidates that don't have enough runs yet to open a version.
  let pending: { member: Member; diffs: string[] }[] = [];

  for (const m of members) {
    if (current.members.length === 0) {
      current.add(m);
      continue;
    }
    const diffs = current.disagreements(m);
    // Fits the template (only differs where the version already varies), or
    // overlaps the version in time → dynamic content, same version.
    if (diffs.length === 0 || current.lastSeen > m.firstSeen.getTime() + opts.graceMs) {
      current.add(m);
      continue;
    }
    pending.push({ member: m, diffs });
    // Pending prompts that share one of this prompt's new values are the same
    // edit (a templated prompt's new version shows up as several hashes).
    const shared = pending.filter(
      (p) => p.member === m || diffs.some((k) => valueAt(p.member, k) === valueAt(m, k)),
    );
    const runs = shared.reduce((n, p) => n + p.member.runs, 0);
    // A lone new text among many unrelated pending ones is a slot value that
    // happened to recur, not an edit — unless it is the only candidate.
    const established = runs >= opts.minRuns && (shared.length >= 2 || pending.length === 1);
    if (!established) continue;

    const sharedSet = new Set(shared.map((p) => p.member));
    for (const p of pending) if (!sharedSet.has(p.member)) current.add(p.member);
    groups.push(current.members);
    current = new Group();
    for (const p of shared) current.add(p.member);
    pending = [];
  }
  for (const p of pending) current.add(p.member);
  if (current.members.length > 0) groups.push(current.members);
  return groups;
}

// --- rendering --------------------------------------------------------------

function render(family: Family, members: Member[]): InferredVersion {
  const canonical = members.reduce((best, m) => (m.runs > best.runs ? m : best), members[0] as Member);
  // Re-align against this version's own canonical so the template reads as
  // the most-run prompt with only this version's variation blanked out.
  const aligned =
    canonical === family.canonical
      ? members.map((m) => m.aligned)
      : members.map((m) => align(canonical.lines, m.lines));
  const values = new Map<string, Set<string>>();
  for (const a of aligned) {
    for (const [key, value] of a) {
      let set = values.get(key);
      if (!set) {
        set = new Set([SAME]);
        values.set(key, set);
      }
      set.add(value);
    }
  }
  // Varying positions: replaced canonical lines and insertion points.
  const replaced = new Set<number>();
  const inserts = new Set<number>();
  for (const [key, set] of values) {
    if (set.size < 2) continue;
    const idx = Number(key.slice(4));
    if (key.startsWith("rep:")) {
      let span = 1;
      for (const v of set) if (v !== SAME) span = Math.max(span, Number(v.split("\n", 1)[0]) || 1);
      for (let i = idx; i < idx + span; i++) replaced.add(i);
    } else inserts.add(idx);
  }
  const out: string[] = [];
  let slotCount = 0;
  const pushSlot = () => {
    if (out[out.length - 1] !== SLOT_LINE) {
      out.push(SLOT_LINE);
      slotCount++;
    }
  };
  for (let i = 0; i <= canonical.lines.length; i++) {
    if (inserts.has(i)) pushSlot();
    if (i === canonical.lines.length) break;
    if (replaced.has(i)) pushSlot();
    else out.push(canonical.lines[i] as string);
  }

  const ordered = [...members].sort((a, b) => a.firstSeen.getTime() - b.firstSeen.getTime());
  return {
    template: out.join("\n"),
    hashes: ordered.map((m) => m.hash),
    slotCount,
    runs: members.reduce((n, m) => n + m.runs, 0),
    firstSeen: new Date(Math.min(...members.map((m) => m.firstSeen.getTime()))),
    lastSeen: new Date(Math.max(...members.map((m) => m.lastSeen.getTime()))),
  };
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/lib/range.ts; derived here under Apache-2.0.
 */
import {
  endOfDay,
  endOfMonth,
  format,
  startOfDay,
  startOfMonth,
  subDays,
  subHours,
  subMonths,
} from "date-fns";

export type RangeValue = {
  /** Originating preset key, or "custom" for a calendar-selected range. */
  key: string;
  label: string;
  from: Date;
  to: Date;
};

type Preset = {
  key: string;
  label: string;
  resolve: (now: Date) => { from: Date; to: Date };
};

export const RANGE_PRESETS: Preset[] = [
  {
    key: "1h",
    label: "Last hour",
    resolve: (n) => ({ from: subHours(n, 1), to: n }),
  },
  {
    key: "24h",
    label: "Last 24 hours",
    resolve: (n) => ({ from: subHours(n, 24), to: n }),
  },
  {
    key: "3d",
    label: "Last 3 days",
    resolve: (n) => ({ from: subDays(n, 3), to: n }),
  },
  {
    key: "7d",
    label: "Last 7 days",
    resolve: (n) => ({ from: subDays(n, 7), to: n }),
  },
  {
    key: "30d",
    label: "Last 30 days",
    resolve: (n) => ({ from: subDays(n, 30), to: n }),
  },
  {
    key: "90d",
    label: "Last 90 days",
    resolve: (n) => ({ from: subDays(n, 90), to: n }),
  },
  {
    key: "today",
    label: "Today",
    resolve: (n) => ({ from: startOfDay(n), to: n }),
  },
  {
    key: "month",
    label: "This month",
    resolve: (n) => ({ from: startOfMonth(n), to: n }),
  },
  {
    key: "lastMonth",
    label: "Last month",
    resolve: (n) => {
      const start = startOfMonth(subMonths(n, 1));
      return { from: start, to: endOfMonth(start) };
    },
  },
];

export function resolvePreset(key: string, now: Date = new Date()): RangeValue {
  const p = RANGE_PRESETS.find((x) => x.key === key) ?? RANGE_PRESETS[1]!;
  const { from, to } = p.resolve(now);
  return { key: p.key, label: p.label, from, to };
}

export function defaultRange(): RangeValue {
  return resolvePreset("24h");
}

/** A calendar-selected absolute range (whole days, inclusive of the end day). */
export function customRange(from: Date, to: Date): RangeValue {
  const f = startOfDay(from);
  const t = endOfDay(to);
  return { key: "custom", label: formatRangeLabel(f, t), from: f, to: t };
}

/** An absolute range at full time precision — produced by dragging a zoom
 * selection on a chart (and used to restore stored custom ranges verbatim).
 * Whole-day ranges keep the calendar picker's date-only label. */
export function exactRange(from: Date, to: Date): RangeValue {
  return { key: "custom", label: formatExactLabel(from, to), from, to };
}

function formatExactLabel(from: Date, to: Date): string {
  const wholeDays =
    from.getTime() === startOfDay(from).getTime() &&
    to.getTime() === endOfDay(to).getTime();
  if (wholeDays) return formatRangeLabel(from, to);
  const sameDay = startOfDay(from).getTime() === startOfDay(to).getTime();
  if (sameDay) return `${format(from, "MMM d, HH:mm")} – ${format(to, "HH:mm")}`;
  const sameYear = from.getFullYear() === to.getFullYear();
  const fmt = sameYear ? "MMM d, HH:mm" : "MMM d, yyyy HH:mm";
  return `${format(from, fmt)} – ${format(to, fmt)}`;
}

/** Absolute readout of a resolved window, minute precision — "Aug 10, 14:32 –
 * Aug 11, 14:32". The year only appears when it isn't the current one. */
export function formatRangeWindow(
  from: Date,
  to: Date,
  now: Date = new Date()
): string {
  const fmt = (d: Date) =>
    format(
      d,
      d.getFullYear() === now.getFullYear()
        ? "MMM d, HH:mm"
        : "MMM d, yyyy, HH:mm"
    );
  return `${fmt(from)} to ${fmt(to)}`;
}

export function formatRangeLabel(from: Date, to: Date): string {
  const sameDay = startOfDay(from).getTime() === startOfDay(to).getTime();
  if (sameDay) return format(from, "MMM d, yyyy");
  const sameYear = from.getFullYear() === to.getFullYear();
  return `${format(from, sameYear ? "MMM d" : "MMM d, yyyy")} – ${format(
    to,
    "MMM d, yyyy"
  )}`;
}

