/** Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted AS-IS from .reference/foglamp/apps/web/src/components/app/header-slot.tsx; derived under Apache-2.0.
 */
"use client";

import {
  createContext,
  useContext,
  useCallback,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";

/**
 * Lets a page's `Toolbar` lift its trailing controls (range picker, "New …"
 * button) into the `PageHeader`'s actions area when they'd otherwise wrap
 * under the filters. The header registers its actions element here; the
 * toolbar portals into it. Provided once by the app shell, so the two can be
 * siblings anywhere in a page tree.
 */
const HeaderActionsSlotContext = createContext<{
  el: HTMLElement | null;
  setEl: (el: HTMLElement | null) => void;
} | null>(null);

export function HeaderActionsSlotProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  const [el, setEl] = useState<HTMLElement | null>(null);
  const value = useMemo(() => ({ el, setEl }), [el]);
  return (
    <HeaderActionsSlotContext.Provider value={value}>
      {children}
    </HeaderActionsSlotContext.Provider>
  );
}

export function useHeaderActionsSlot() {
  return useContext(HeaderActionsSlotContext);
}

// ---------------------------------------------------------------------------
// Anticipated width changes
// ---------------------------------------------------------------------------

/**
 * Panels that animate their width (the Foggy chat) shrink the content area
 * over several frames. A toolbar measuring the *current* width would see the
 * row overflow — and wrap — a frame before it lifts its controls. Reporting
 * the panel's target width here lets the toolbar measure against the width
 * the content area is *about* to have, so it lifts on the first frame.
 */
type Reserve = { target: number; el: HTMLElement | null };

const LayoutReserveContext = createContext<{
  reserve: Reserve;
  setReserve: (r: Reserve) => void;
} | null>(null);

export function LayoutReserveProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  const [reserve, setReserve] = useState<Reserve>({ target: 0, el: null });
  const value = useMemo(() => ({ reserve, setReserve }), [reserve]);
  return (
    <LayoutReserveContext.Provider value={value}>
      {children}
    </LayoutReserveContext.Provider>
  );
}

/** Called by an animating panel: its final width and the element animating
 * toward it. */
export function useReportLayoutReserve(target: number) {
  const ctx = useContext(LayoutReserveContext);
  const ref = useRef<HTMLElement>(null);
  const setReserve = ctx?.setReserve;
  useLayoutEffect(() => {
    setReserve?.({ target, el: ref.current });
  }, [setReserve, target]);
  return ref;
}

/** Pixels the content area is still going to lose (0 while nothing is
 * shrinking — growth is never anticipated: staying lifted a moment longer
 * doesn't wrap anything). */
export function usePendingShrink(): () => number {
  const ctx = useContext(LayoutReserveContext);
  const reserve = ctx?.reserve;
  return useCallback(() => {
    if (!reserve?.el) return 0;
    return Math.max(
      0,
      reserve.target - reserve.el.getBoundingClientRect().width
    );
  }, [reserve]);
}

"use client";

/** Original design by Gustavo Fior (@gustavo-fior), Abdul Haidar and Foglamp Labs.
 * Extracted from foglamp-labs/foglamp under the Apache-2.0 license. */

import { TableCell } from "../ui/table";
import {
	Tooltip,
	TooltipContent,
	TooltipTrigger,
} from "../ui/tooltip";
import { cn } from "../lib/utils";
import type { ReactNode } from "react";

// Traffic-light shades for the five quintile buckets. Green = cheapest/fastest,
// red = priciest/slowest. Light uses 600, dark uses 400 for contrast. Literal
// classes so Tailwind keeps them.
export const HEAT_SHADES = [
	"text-green-600 dark:text-green-400",
	"text-yellow-600 dark:text-yellow-400",
	"text-amber-600 dark:text-amber-400",
	"text-orange-600 dark:text-orange-400",
	"text-red-600 dark:text-red-400",
] as const;

// Labels for the five quintile buckets, shown in cell tooltips.
export const PCT_RANGE = [
	"0–20th",
	"20–40th",
	"40–60th",
	"60–80th",
	"80–100th",
] as const;

/** Which quintile bucket (0..4) `value` falls in against the global `thresholds`
 * (the 20/40/60/80th percentiles). null when there's nothing to place. */
export function percentileBucket(
	value: number | null | undefined,
	thresholds: number[],
) {
	if (!value || value <= 0 || thresholds.length === 0) return null;
	let i = 0;
	for (const t of thresholds) if (value > t) i += 1;
	return Math.min(i, HEAT_SHADES.length - 1);
}

/** A right-aligned numeric cell tinted by its percentile bucket, with a tooltip
 * naming the bucket. Unbucketed values render plain — muted for null/unpriced.
 *
 * - `metric` controls tooltip wording: "cost" (default) → "cheapest/priciest",
 *   "duration" → "fastest/slowest", "spend" → "cheapest/priciest" with "by spend".
 * - `bold` applies `font-medium` to the cell text.
 * - `mutedWhenZero` also dims zero-cost cells (use when zero is unpriced). */
export function HeatCell({
	value,
	thresholds,
	metric = "cost",
	bold,
	mutedWhenZero,
	children,
}: {
	value: number | null | undefined;
	thresholds: number[];
	metric?: "cost" | "duration" | "spend";
	bold?: boolean;
	mutedWhenZero?: boolean;
	children: ReactNode;
}) {
	const bucket = percentileBucket(value, thresholds);
	const muted = mutedWhenZero ? value == null || value <= 0 : value == null;
	const className = cn(
		"text-right tabular-nums",
		bold && "font-medium",
		muted ? "text-muted-foreground/40" : bucket != null && HEAT_SHADES[bucket],
	);
	if (bucket == null) {
		return <TableCell className={className}>{children}</TableCell>;
	}
	const tip = buildTip(bucket, metric);
	return (
		<TableCell className={className}>
			<Tooltip>
				<TooltipTrigger render={<span className="cursor-default" />}>
					{children}
				</TooltipTrigger>
				<TooltipContent>{tip}</TooltipContent>
			</Tooltip>
		</TableCell>
	);
}

function buildTip(bucket: number, metric: "cost" | "duration" | "spend") {
	if (metric === "duration") {
		const extreme =
			bucket === 0 ? " · fastest" : bucket === 4 ? " · slowest" : "";
		return `${PCT_RANGE[bucket]} percentile by duration${extreme}`;
	}
	const label = metric === "spend" ? "spend" : "cost";
	const extreme =
		bucket === 0 ? " · cheapest" : bucket === 4 ? " · priciest" : "";
	return `${PCT_RANGE[bucket]} percentile by ${label}${extreme}`;
}

"use client";

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/app/agent-icon.tsx; derived here under Apache-2.0.
 */
import { IconGhost, IconGhostFilled } from "@tabler/icons-react";

import { cn } from "../../lib/utils";

// A spread of mid-tone hues that read on both light and dark surfaces. One is
// picked deterministically from the agent name (see `agentColor`), so an agent
// always gets the same color while different agents stay visually distinct —
// the same idea as the per-project placeholder icons.
const AGENT_COLORS = [
  "#ef4444", // red-500
  "#f97316", // orange-500
  "#f59e0b", // amber-500
  "#84cc16", // lime-500
  "#22c55e", // green-500
  "#10b981", // emerald-500
  "#14b8a6", // teal-500
  "#06b6d4", // cyan-500
  "#0ea5e9", // sky-500
  "#3b82f6", // blue-500
  "#6366f1", // indigo-500
  "#8b5cf6", // violet-500
  "#a855f7", // purple-500
  "#d946ef", // fuchsia-500
  "#ec4899", // pink-500
  "#f43f5e", // rose-500
];

// djb2 string hash — small, fast, and stable across runs so the color is
// reproducible for a given name.
function hashString(str: string): number {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash + str.charCodeAt(i)) | 0;
  }
  return Math.abs(hash);
}

/** A reproducible accent color (hex) for an agent, derived from its name. */
export function agentColor(name: string | null | undefined): string {
  const key = name?.trim() ?? "";
  if (!key) return AGENT_COLORS[0];
  return AGENT_COLORS[hashString(key) % AGENT_COLORS.length];
}

/** A ghost glyph tinted with the agent's reproducible color. By default it renders
 * the outline variant with a faint `fill-current/20` wash — the standard treatment
 * for an agent's custom-color icon everywhere it appears (filters, breakdowns,
 * tables, headers). `filled` opts into the solid variant when needed; size is set
 * via `className` (defaults to `size-4`). The color is applied inline so it
 * overrides any text-color class, and `fill-current` resolves to that same color. */
export function AgentIcon({
  name,
  filled = false,
  className,
}: {
  name: string | null | undefined;
  filled?: boolean;
  className?: string;
}) {
  const Icon = filled ? IconGhostFilled : IconGhost;
  return (
    <Icon
      className={cn("size-4 shrink-0", !filled && "fill-current/20", className)}
      style={{ color: agentColor(name) }}
    />
  );
}

