      </div>
      {/* Right: run count + share-of-runs bar. */}
      <div className="flex shrink-0 flex-col items-end gap-1">
        <span
          className="text-sm tabular-nums"
          title={`Last seen ${formatDateTime(v.lastSeen)}`}
        >
