// Same bubble as the session page: user text in a card, assistant markdown
// as prose with a hover copy button.
export function Bubble({
  who,
  text,
}: {
  who: "user" | "assistant";
  text: string;
}) {
  const isUser = who === "user";
  return (
    <div className="group/bubble flex gap-3">
      <Avatar who={who} />
      <div
        className={
          isUser
            ? "min-w-0 flex-1 corner-squircle rounded-lg squircle:rounded-2xl bg-card dark:bg-muted-foreground/10 shadow-(--custom-shadow) px-3 py-2.5"
            : "min-w-0 flex-1 px-1 py-0"
        }
      >
        {isUser ? (
          <p className="whitespace-pre-wrap wrap-break-word text-sm">{text}</p>
        ) : (
          <div className="flex items-start justify-between gap-2">
            <div className="min-w-0 flex-1 text-sm leading-relaxed [&_li]:my-0.5 [&_ol]:my-1.5 [&_ol]:list-decimal [&_ol]:pl-5 [&_p]:my-1.5 [&_pre]:my-2 [&_ul]:my-1.5 [&_ul]:list-disc [&_ul]:pl-5 *:last:mb-0 [&>*:first-child>*:first-child]:mt-0 [&>*:first-child>*:first-child>*:first-child]:mt-0">
              <Streamdown
                components={markdownComponents}
                controls={{ table: false }}
              >
                {text}
              </Streamdown>
            </div>
            <div className="shrink-0 opacity-0 transition-opacity group-hover/bubble:opacity-100">
              <CopyButton value={text} title="Copy output" />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/** The assistant slot for a structured answer: the same row as a prose
 * bubble, with the JSON viewer where the markdown would be. One block per
 * value, so an output that is a parts array reads as its pieces. The block's
 * own scroll cap is lifted — the drawer clamps the whole exchange instead. */
export function JsonBubble({ data }: { data: unknown[] }) {
  const copy = data
    .map((d) => {
      try {
        return JSON.stringify(d, null, 2);
      } catch {
        return String(d);
      }
    })
    .join("\n\n");
  return (
    <div className="group/bubble flex gap-3">
      <Avatar who="assistant" />
      <div className="flex min-w-0 flex-1 items-start justify-between gap-2 px-1">
        <div className="flex min-w-0 flex-1 flex-col gap-2">
          {data.map((d, i) => (
            <JsonBlock
              // biome-ignore lint/suspicious/noArrayIndexKey: positional
              key={i}
              data={d}
              className="max-h-none corner-squircle rounded-lg squircle:rounded-2xl bg-card p-3 shadow-(--custom-shadow) dark:bg-muted-foreground/10"
            />
          ))}
        </div>
        <div className="shrink-0 opacity-0 transition-opacity group-hover/bubble:opacity-100">
          <CopyButton value={copy} title="Copy output" />
        </div>
      </div>
    </div>
  );
}

/** Why a run has no output: an agent run that stopped after a tool call
 * never produced a final answer (the usual case for a blank root span). */
export function emptyOutputHint(spans: { spanType: string }[]): string {
  return spans.some((s) => s.spanType === "tool")
    ? "No final answer, the run ended after a tool call."
    : "No output was recorded for this run.";
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/app/tool-breakdown-card.tsx; decoupled from its query layer under Apache-2.0.
 */
"use client";

import {
	useCallback,
	useLayoutEffect,
	useRef,
	useState,
} from "react";
import { IconTool } from "@tabler/icons-react";

import { formatCount, formatDuration, formatPercent } from "../lib/format";
import { cn } from "../lib/utils";
import {
	Card,
	CardContent,
	CardHeader,
	CardTitle,
} from "../ui/card";
import {
	Empty,
	EmptyContent,
	EmptyDescription,
	EmptyHeader,
	EmptyMedia,
	EmptyTitle,
} from "../ui/empty";
import { Skeleton } from "../ui/skeleton";
import { ToolIcon } from "./leaf/tool-icon";
import { useDelayedLoading } from "../hooks/use-app-hooks";

export type ToolBreakdownItem = {
	toolName: string;
	callCount: number;
	errorCount: number;
	runCount: number;
	totalRunCount: number;
	latencyMs: {
		p50: number;
		p95: number;
		p99: number;
	};
};

/**
 * Which tools an agent leans on: per-tool call volume, error rate, and latency
 * quantiles over the window, most-called first. Pass data from any query,
 * server component, or fixture; no project or backend context is required.
 */
export function ToolBreakdownView({
	tools,
	isLoading = false,
	isUpdating = false,
	title = "Tools",
	className,
}: {
	tools: readonly ToolBreakdownItem[];
	isLoading?: boolean;
	isUpdating?: boolean;
	title?: string;
	className?: string;
}) {
	const skeleton = useDelayedLoading(isLoading);
	// Share bars are scaled to the most-called tool, like the overview's
	// breakdown cards scale to the top cost.
	const maxCalls = Math.max(1, ...tools.map((t) => t.callCount));

	return (
		<Card
			size="sm"
			className={cn("pb-0! group-data-[size=sm]/card:pb-0!", className)}
		>
			<CardHeader>
				<CardTitle>{title}</CardTitle>
			</CardHeader>
			<CardContent className="mt-1">
				{!isLoading && tools.length === 0 ? (
					<ToolEmptyState />
				) : (
					// One ScrollFade for both the skeleton and the loaded rows so the
					// fade never remounts when the data lands (mirrors the overview).
					<ScrollFade
						className="max-h-72 pr-1"
						containerClassName={cn(
							"transition-opacity",
							isUpdating
								? "opacity-50 delay-150 duration-300"
								: "duration-150",
						)}
					>
						{isLoading ? (
							<ToolRowsSkeleton skeleton={skeleton} />
						) : (
							<div className="divide-y divide-border/40 pb-6">
								{tools.map((t) => (
									<div
										key={t.toolName}
										className="flex items-center justify-between gap-6 px-0.5 py-3 first:pt-0 last:pb-0"
									>
										{/* Left: name + secondary metrics (mirrors BreakdownRow). */}
										<div className="min-w-0 flex-1">
											<div className="flex items-center gap-1.75">
												<ToolIcon
													name={t.toolName}
													className="size-3.25 shrink-0 text-blue-500"
												/>
												<span className="truncate text-sm font-medium">
													{t.toolName || "unnamed"}
												</span>
											</div>
											<div className="mt-1 text-xs tabular-nums text-muted-foreground/70">
												p50 {formatDuration(t.latencyMs.p50)} · p95{" "}
												{formatDuration(t.latencyMs.p95)} · p99{" "}
												{formatDuration(t.latencyMs.p99)}
												{t.errorCount > 0 && (
													<span className="text-red-500/80">
														{" "}
														· {formatPercent(t.errorCount / t.callCount)} err
													</span>
												)}
											</div>
										</div>
										{/* Right: call count + share-of-calls bar. */}
										<div className="flex shrink-0 flex-col items-end gap-1">
											<span className="text-sm tabular-nums">
												{formatCount(t.callCount)}
												{t.callCount === 1 ? " call" : " calls"}
											</span>
											{t.totalRunCount > 0 && (
												<span className="text-xs tabular-nums text-muted-foreground/70">
													{formatPercent(t.runCount / t.totalRunCount)} of runs
												</span>
											)}
											<div className="h-0.5 w-14 overflow-hidden rounded-full bg-muted-foreground/10">
												<div
													className="ml-auto h-full rounded-full bg-blue-500"
													style={{
														width: `${Math.max(2, (t.callCount / maxCalls) * 100)}%`,
													}}
												/>
											</div>
										</div>
									</div>
								))}
							</div>
						)}
					</ScrollFade>
				)}
			</CardContent>
		</Card>
	);
}

